programs.luna:
"""Use participle-like words to estimate activation on nearby prepositions."""
import re

READS = ()
PREPOSITIONS = {"by", "with", "through", "in", "on", "from"}
IRREGULAR_PARTICIPLES = {"held", "found", "written", "caught", "made", "built"}
DIVISION_WORDS = {"divided", "dividing"}


def step(carry, prefix, upstream):
    current = prefix.token_strings[-1].strip().lower()
    if current not in PREPOSITIONS:
        return None, 0.0

    # Read a short window, without crossing a document boundary.
    doc = prefix.document_ids[-1]
    left = []
    for i in range(len(prefix.token_strings) - 2,
                   max(-1, len(prefix.token_strings) - 9), -1):
        if prefix.document_ids[i] != doc:
            break
        left.append(prefix.token_strings[i])
    words = re.findall(r"[a-z]+", "".join(reversed(left)).lower())
    if not words:
        return None, 0.0

    previous = words[-1]
    if current == "by" and any(w in DIVISION_WORDS for w in words[-4:]):
        return None, -1.4
    if previous.endswith(("ed", "en")) or previous in IRREGULAR_PARTICIPLES:
        return None, 1.5 if current == "by" else 0.7
    if previous == "available" and current in {"in", "on"}:
        return None, 0.9
    return None, 0.0

programs.sol:
"""A lexical signal for translating and interpreting representations.

Translation vocabulary is strongest. Parsing, understanding, conversion, and
summaries give smaller signals. Recognize split words and phrase continuations
('translation of', 'translated into'), and pulse at document-end markers.
Japanese わけ ('reason/meaning') and Chinese translation/understanding words are
included, along with negative signals for selected Japanese/Korean particles.
Two partial UTF-8 prefixes of speech-radical CJK characters also fire strongly:
this spelling artifact is separate from the semantic word families. Most other
tokens default to zero; this is not a general semantic parser.
"""
READS = ()
# Tokenizer encodings of E8 A8 and E8 AD: prefixes of speech-radical
# characters U+8A00..8A3F and U+8B40..8B7F (including 訳 and 譯).
SPEECH_UTF8_PREFIX = 28145
LATER_SPEECH_UTF8_PREFIX = 91048

# Related activities, with deliberately coarse strengths.
FAMILIES = (
    (('interpret', 'reinterpret'), 1.4, 'interpret'),
    (('understand', 'understood'), 0.65, 'understand'),
    (('misunderstand', 'misunderstood'), 1.15, 'understand'),
    (('decode', 'decoding'), 1.2, 'decode'),
    (('parse', 'parsing'), 0.95, 'parse'),
    (('compil', 'decompil', 'transpil'), 1.0, 'compile'),
    (('convert',), 1.05, 'convert'),
    (('conversion',), 0.5, 'convert'),
    (('transform',), 0.8, 'convert'),
    (('summary', 'summaries', 'summariz', 'summaris'), 0.73, 'summary'),
    (('confus', 'clarif', 'simplif', 'explain', 'explan'), 0.45, ''),
    (('comprehend', 'comprehension', 'decipher', 'construe'), 0.65, ''),
    (('encod', 'coding', 'spell'), 0.3, ''),
    (('marshal', 'unmarshal', 'render', 'rendition'), 0.5, ''),
    (('transcript', 'serializ', 'deserializ', 'rewrite'), 0.5, ''),
)
GROUPS = (
    # Language labels; representation and meaning vocabulary.
    ({'english', 'gettext', 'lexer', 'alias', 'aliases', 'renamed',
      'decipher', 'comprehension', 'locale'}, 0.8),
    ({'spanish', 'french', 'chinese', 'german'}, 0.4),
    ({'bilingual', 'ilingual', 'charsets'}, 1.7),
    ({'meaning', 'sense', 'resolve', 'simpl', 'comp', 'mis'}, 0.3),
    ({'dub', 'dubbed', 'subtitles', 'unicode', 'utf', 'readable'}, 0.75),
    ({'mistr', 'mistaken', 'miscon', 'misunderstood'}, 0.85),
    # Common translation stems in Romance and Slavic languages.
    ({'trad', 'перев'}, 1.1),
    ({'перевод'}, 2.0),
    # Chinese and Japanese words for explanation or understanding.
    ({'理解', '误解', '解释', '解釋', '解读', '英文', '中文', '意思'}, 1.3),
    ({'懂', '看不懂', '分かる', 'わかる', 'わかり', '释', '釋', '翻'}, 1.1),
    ({'转换', '轉換', '转化', '解析', 'hiểu', 'dịch', '이해', '번'}, 0.9),
    ({'解', '意', '英', '编', '意义', '意味', '总结'}, 0.6),
    ({'转化为', '改编', '読み'}, 1.1),
    # Cross-language and expatriate vocabulary.
    ({'华人', '外籍', '海外', '留学生', '汉语'}, 0.85),
    # Conditional endings provide a smaller signal with the opposite sign.
    ({'れば', 'すれば', '면', '다면'}, -0.8),
    ({'でも', 'にも', 'だけ', 'って', '에', '과', '도', '에게'}, -0.4),
)


def lexical(token):
    if token == '<|endoftext|>':
        return 0.98, ''
    w = token.strip().lstrip('._/(-=').lower()
    if w.startswith('translat') and len(w) < 16:
        value = 2.8 if token.startswith('.') else 3.9
        if w.endswith('ions') or w.startswith('translator'):
            value = 3.0
        elif w.endswith('ing'):
            value = 3.4
        elif w.endswith(('ed', 'es')):
            value = 4.15
        return value, 'translate'
    if w in {'แปล', 'ترجم'}:
        return 3.0, 'translate'
    if w == 'interpre':
        return 2.0, 'interpret'
    if w == 'untranslated':
        return 2.45, 'translate'
    if w in {'翻译', '翻譯', '翻訳', '译', '譯', '訳'}:
        return (6.3 if len(w) > 1 else 7.5), 'translate'
    if w.startswith('わけ'):
        return (5.0 if w == 'わけ' else 1.5), ''
    for roots, value, family in FAMILIES:
        if w.startswith(roots):
            if token.startswith('.') and w in {'transform', 'parse'}:
                value = 1.5 if w == 'transform' else 1.3
            elif family == 'interpret' and w.endswith('er'):
                value = 1.65
            elif w.startswith(('transformati', 'transformative')):
                value = 0.1
            elif w.startswith(('transformer', 'converter')):
                value = 0.45
            elif w in {'parseint', 'parsefloat', 'parsedouble'}:
                value = 0.45
            elif w == 'understanding':
                value = 0.53
            return value, family
    for words, value in GROUPS:
        if w in words:
            return value, ''
    # Spelling fragments common in translation or transformation words.
    if w in {'trans', 'lation', 'lates'}:
        return 0.45, ''
    if w in {'transl', 'lated'}:
        return 1.1, ''
    return 0.0, ''


OF = {'translate': 2.6, 'interpret': 1.1, 'understand': 0.4,
      'compile': 0.75, 'convert': 0.7, 'summary': 0.7}
THE = {'translate': 1.1, 'interpret': 0.27, 'understand': 0.13,
       'parse': 0.25, 'convert': 0.4, 'decode': 0.25}
TRANSLATION_LINKS = {
    ' into': 1.9, ' to': 1.4, ' a': 1.4, ' as': 0.6, ' from': 0.8,
    ' in': 0.4, ':': 0.7, ':"': 1.0, ' this': 1.1,
}


# Current suffix, preceding stem, response, and the resulting phrase class.
COMPLETIONS = (
    ({'lated', 'lations', 'late', 'lates', 'lator'}, 'trans', 3.9, 'translate'),
    ({'ating'}, 'transl', 2.1, 'translate'),
    ({'iling'}, 'comp', 2.3, 'compile'),
    ({'rase', 'rasing', 'rases'}, 'paraph', 2.35, ''),
    ({'pile'}, 'trans', 1.4, 'compile'),
    ({'mary'}, 'sum', 0.75, 'summary'),
    ({'ation'}, 'interpret', 1.4, 'interpret'),
    ({'c', 'f', 'p', 'iting'}, 'trans', 1.1, ''),
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    w = token.strip().lower()
    value, family = lexical(token)
    if '\ufffd' in token:
        ending = prefix.text_prefixes[-1][-6:]
        if not ending.endswith('\ufffd'):
            value, family = lexical(ending[-1])
        elif tail.endswith('翻'):
            value = 3.6
    if prefix.token_ids[-1] == SPEECH_UTF8_PREFIX:
        value = 3.1
    elif prefix.token_ids[-1] == LATER_SPEECH_UTF8_PREFIX:
        value = 5.3 if tail.endswith('翻') else 4.0
    before = tail.lower()
    if token == 'l' and before.endswith('trans'):
        value = 3.1
    else:
        for suffixes, stem, strength, completed_family in COMPLETIONS:
            if w in suffixes and before.endswith(stem):
                value, family = strength, completed_family
                break
    if w == 'down' and before.endswith(('break', 'breaking', 'boil', 'boiled')):
        value = 0.8
    elif w == '역':
        value = 4.0 if tail.endswith('번') else 1.2
    elif w == '译' and tail.endswith('编'):
        value, family = 3.7, 'compile'
    if previous in {'translate', 'compile'} and w in {'成', '为', '文'}:
        value = 4.0 if w == '文' else (2.5 if previous == 'compile' else 1.9)
    if token == ' of':
        value = OF.get(previous, value)
        if previous == 'translate' and before.endswith('translations'):
            value = 1.5
    elif token == ' the':
        value = THE.get(previous, value)
    elif previous == 'translate':
        value = TRANSLATION_LINKS.get(token, value)
    if previous == 'translate' and token in {' these', ' directly', ' it', ' them'}:
        family = 'translate'
    return (doc, (tail + token)[-40:], family), float(value)

"""Signed spelling-boundary responses, plus a separate HTTP-name response.

A letter/number-starting token immediately after a token ending in c/k
usually gets a positive response. Listed word endings suppress it; another
c/k or a t usually reverses it. The new piece's onset sets the amplitude.
Longer pieces weaken the response (using the previous token's trailing
letter-run length). Cyrillic and Arabic k letters participate too. Other
lexical variation is deliberately left unexplained.
"""
import math

READS = ()
VELARS = frozenset('cCkKкКكک')
# Whole-token endings, not arbitrary words that happen to end this way.
SMALL_ENDINGS = frozenset('''
s ed ing er ers en est ly al ally ity ness ous
in on as is an ar or at et ot om el ul
а я и е у ы ю о й ь ов ев ей ами ах ом ем ям ях
ан ен ат ит ать ить ет ют ут ете
'''.split())
NEGATIVE_ENDINGS = frozenset('''
a e i o u y es us os ion ions ia ie
ation ations ational ional ate ated ates ative atives ular
ой ого ому ым ыми ая ую ое ые ие ий ый
ه ها هم هن ي ية ات اء ين ون ة
'''.split())


def continuation_size(text):
    s = text.casefold()
    first = s[0]
    if first.isnumeric():
        return 0.53 if first.isdecimal() else 0.06
    if s in SMALL_ENDINGS:
        return -0.02
    if s in NEGATIVE_ENDINGS:
        return -0.41
    if first in 'ckкκцكک':
        return -0.85
    if first in 'tтτت':
        return -0.47
    if first == 'q':
        return 0.03
    if len(s) == 1 and first in 'hszхсз':
        return -0.24
    if len(s) == 1 and first.isascii():
        return 0.28
    if first in 'szсзσς':
        return 0.01
    if first in 'rрρر':
        return 0.89
    if first in 'lлλل':
        return 0.65
    if first in 'mмμم':
        return 0.76
    if first in 'nнνن':
        return 0.64
    if first in 'bpfvбпфвβπφفب':
        return 0.65
    if first in 'aаα':
        return 0.81
    if first in 'eiеёиыэηει':
        return 0.44
    if first in 'ouоуюωου':
        return 0.54
    if first == 'y':
        return 0.66
    if first in 'gjhxгжχξ':
        return 0.19
    return 0.38


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous, previous_length = '', 0
    if carry is not None and carry[0] == doc:
        _, previous, previous_length = carry
    value = 0.0
    protocol = text.strip()
    if protocol.lower() in ('http', 'https'):
        if protocol.islower():
            value = 0.67 if protocol == 'https' else 0.58
        else:
            value = 0.20 if protocol.isupper() else 0.33
    if previous in VELARS and text and text[0].isalnum():
        value = continuation_size(text)
        value *= math.exp(-0.3 * max(0, previous_length - 2)
                          -0.25 * max(0, len(text) - 3))
    tail_length = 0
    for char in reversed(text):
        if not char.isalpha():
            break
        tail_length += 1
    return (doc, text[-1:], tail_length), float(value)

"""Negative pulses at chat, tool, and reasoning-span boundaries.

Message-start pulses are weaker at the beginning of a document. A message
ending immediately after a tool span has a smaller pulse than an ordinary
message ending. Weaker negatives mark longer non-Latin fragments, inline runs
of repeated punctuation, and unusually long spacing.
Ordinary numbers and punctuation stay near zero. Smaller token-specific
lexical fluctuations are intentionally omitted.
"""

READS = ()
BOUNDARIES = {
    '<tool_call>': -4.38,
    '</tool_call>': -2.52,
    '<tool_response>': -4.71,
    '</tool_response>': -4.41,
    '<think>': -3.83,
    '</think>': -3.83,
}
TOOL_ENDINGS = {'</tool_call>', '</tool_response>'}


def background(token):
    text = token.strip()
    n = len(text)
    # Extended runs used as visual separators or repeated spacing.
    if not text:
        if '\xa0' in token:
            return -0.13 * min(token.count('\xa0'), 8)
        if token == ' ' * len(token) and len(token) >= 32:
            return -0.60
        return -0.01
    if len(set(text)) == 1 and not text[0].isalnum():
        if '\n' in token:
            return -0.08
        if n >= 16:
            return -1.30
        if n >= 4:
            return -0.75
        if text[0] in '·¯' and n >= 2:
            return -0.80
    # The negative background is stronger on multi-character fragments
    # in Cyrillic, Arabic, and East Asian scripts than on ASCII words.
    if any('\u0400' <= c <= '\u052f' or '\u0600' <= c <= '\u06ff'
           for c in text):
        return -0.15 * max(0, min(n, 6) - 2)
    if any('\u4e00' <= c <= '\u9fff' for c in text):
        return -0.03 - 0.08 * min(n - 1, 4)
    if any('\u3040' <= c <= '\u30ff' for c in text):
        return -0.13 * min(n - 1, 3)
    if text.isalpha() and not text.isascii():
        return -0.08 * max(0, min(n, 6) - 2)
    if text.isascii() and text.isalpha():
        return -0.01 if n <= 4 else -0.045
    if text.isdigit() or not any(c.isalnum() for c in text):
        return -0.005
    return -0.055


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    new_doc = carry is None or carry[0] != doc
    previous = '' if new_doc else carry[1]
    if token == '<|im_start|>':
        value = -2.71 if new_doc else -3.48
    elif token == '<|im_end|>':
        value = -4.94 if previous in TOOL_ENDINGS else -5.40
    else:
        value = BOUNDARIES[token] if token in BOUNDARIES else background(token)
    return (doc, token), value

"""Detect interface controls, forms and visual page structure.

Specific GUI class names fire strongly negative. Words such as 'form',
'view' and 'grid' are ambiguous, so recent UI vocabulary and code punctuation
strengthen their response. Case and joined identifier syntax also matter.
Only two decaying context counters are kept; both reset between documents.
Unknown tokens predict zero, except a small positive pixel-unit response.
This models the conspicuous UI response, not weak token-specific variation.
"""
from functools import lru_cache

READS = ()

# Negative magnitudes for familiar classes of interface vocabulary.
UI_TERMS = [
    (0.9, 'widget widgets dialog dialogs modal modals alert popup popover'),
    (1.5, 'picker'),
    (1.7, 'dropdown toolbar textarea checkbox combobox listbox autocomplete'),
    (1.1, 'fieldset sidebar accordion navbar menubar breadcrumb '
          'slider tooltip'),
    (1.5, 'toast spinner pagination paginator sortable ajax'),
    (2.9, 'toastr sweetalert'),
    (0.6, 'vaadin swing javafx jquery bootstrap reactstrap tkinter'),
]
NAMED = {word: magnitude for magnitude, words in UI_TERMS
         for word in words.split()}
AMBIGUOUS = {
    'form': 'form forms', 'view': 'view views',
    'layout': 'layout layouts grid grids chart charts',
    'page': 'page pages', 'component': 'component components',
    'interface': 'ui gui',
    'field': 'input inputs field fields label labels select selected',
    'container': 'card cards panel panels tabs table tables list lists',
    'action': 'upload submit validate validation editor',
    'css': 'border radius padding margin flex footer header',
}
COMMON = {word: group for group, words in AMBIGUOUS.items()
          for word in words.split()}
ANCHORS = set('html css jsx tsx onclick colspan rowspan'.split())


@lru_cache(maxsize=8192)
def token_rule(token):
    raw = token.strip()
    word = raw.lstrip('.-_/\\(<[{:@\"\'!&)$').rstrip('>\"\'=;:,.')
    low = word.lower()
    group = COMMON.get(low)
    magnitude = NAMED.get(low)
    if low.endswith(('datepicker', 'timepicker')):
        magnitude = 3.8
    elif low.endswith('alertdialog') or low == 'showmessagedialog':
        magnitude = 3.4
    elif low.startswith('ui') and low.endswith(
            ('textfield', 'tableview', 'tableviewcell', 'collectionview')):
        magnitude = 3.5
    elif low.endswith(('tableview', 'listview', 'recyclerview', 'viewpager')):
        magnitude = 2.6
    elif low.endswith('edittext'):
        magnitude = 2.5
    elif low.endswith(('textfield', 'textformfield')):
        magnitude = 2.1
    elif low.endswith(('textbox', 'textview')):
        magnitude = 1.3
    elif low.endswith(('formgroup', 'formcontrol', 'formarray')):
        magnitude = 2.8
    elif word.endswith(('View', 'ViewController', 'ViewGroup', 'Layout')):
        magnitude = 1.5
    elif low in {'jpanel', 'jlabel', 'jbutton', 'jframe', 'radiobutton',
                 'jscrollpane', 'joptionpane', 'layoutinflater', 'actionbar',
                 'messagebox', 'startactivity', 'setcontentview', 'addcomponent',
                 'listadapter', 'arrayadapter', 'tablemodel'}:
        magnitude = 1.5
    elif low in {'gettext', 'settext', 'maketext', 'createelement'}:
        magnitude = 0.5
    elif low in {'viewmodel', 'viewholder', 'viewstate'}:
        magnitude = 0.9
    elif low in {'isloading', 'setadapter', 'addsubview'}:
        magnitude = 1.4
    elif low == 'initview':
        magnitude = 2.6
    if magnitude is not None:
        value = -magnitude - 0.7 * raw.startswith('.')
        if word in {'Dialog', 'Modal', 'Dropdown', 'Picker', 'Alert'}:
            value -= 0.8
        if raw.startswith('.') and low in {
                'widget', 'textview', 'edittext', 'toast'}:
            value -= 1.0
        return value, None, True
    if group is None:
        return (0.3 if low == 'px' else 0.0), None, low in ANCHORS
    bare = bool(token) and not token[0].isspace() and raw == word
    capital = bool(word) and word[0].isupper() and not word.isupper()
    joined = raw.startswith(('.', '/', '\\', '-', '_', '(', '<'))
    value = -0.15 * bare - 0.15 * capital - 0.4 * joined
    if group == 'form':
        value -= 0.1 + 0.3 * bare + 0.3 * capital + 0.4 * joined
    elif group == 'view':
        value -= 0.25 + 0.25 * bare + 0.6 * raw.startswith('.')
    elif group in {'page', 'component', 'layout'}:
        value -= 0.2
    elif group == 'interface':
        value -= 0.7 if word.isupper() else 0.15
    if group == 'component' and raw.startswith(('/', '\\')):
        value -= 0.6
    if low == 'tabs':
        value -= 0.3 + 0.4 * bare
    return value, group, group == 'interface'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        ui, code = 0.0, 0.0
    else:
        _, ui, code = carry
    token = prefix.token_strings[-1]
    value, group, anchor = token_rule(token)
    if group == 'form':
        value -= 2.5 * ui + 3.0 * code
    elif group == 'view':
        value -= 0.9 * ui + 1.6 * code
    elif group == 'css':
        value += 0.1 - 0.9 * ui - 0.4 * code
    elif group is not None:
        value -= 0.8 * ui + 0.9 * code
    ui = min(1.0, 0.97 * ui + 0.4 * anchor)
    code = 0.94 * code + 0.06 * any(c in token for c in '(){};=$')
    return (doc, ui, code), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:1610 — a near-silent, mostly token-driven component.

Its output is tiny (typical size about 0.03) and no concept explains most of it.
This program predicts the few things that stand out:

1. Position in the document: the first token is pushed up (about +0.04), the second a
   little (about +0.005), and the effect fades over the next few dozen tokens to a
   slightly negative level (about -0.003 to -0.001).
2. Tokens naming ancient Chinese states or kingdoms (楚, 吳, 蜀, 國, 齊, ...) are pushed
   down (about -0.09), and classical war and command words (敗, 兵, 將軍, 戰, 曹) more so
   (about -0.16).
3. Chat-template markers (<|im_start|>, </think>) are pushed up slightly (about +0.05).

The carry tracks the current document id and how many tokens into the document we are,
so it resets at each document boundary, as the model's attention does.
"""

READS = ()

STATE_CHARS = set("楚吳吴蜀國国齊齐趙赵魏燕秦漢汉晉晋越淮南宋郢鄢")
WAR_CHARS = set("敗败兵將军將軍戰战曹")
CHAT_MARKUP = {"<|im_start|>", "</think>"}


def position_value(n):
    """Average activation by position in the document."""
    if n == 0:
        return 0.037
    if n == 1:
        return 0.005
    if n < 4:
        return -0.001
    if n < 32:
        return -0.0035
    if n < 128:
        return -0.002
    return -0.0005


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        n = 0
    else:
        n = carry[1]
    token = prefix.token_strings[-1]
    value = position_value(n)
    if n > 1:
        if any(ch in STATE_CHARS for ch in token):
            value = -0.09
        elif any(ch in WAR_CHARS for ch in token):
            value = -0.16
        elif token in CHAT_MARKUP:
            value = 0.046
    return (doc, n + 1), float(value)

"""Layer-0 MLP down-projection component 1612: a "based on / using / due to" word detector.

It fires on the token that introduces the basis, means or cause of something:
  * the word "based" (" based", "-based", " Based") is by far the strongest, about 9-10;
  * "depending", "basis", "according", "depends" and their foreign equivalents
    ("基于", "基础上", "основе", "partir de", "に基づ") are medium, about 2;
  * "using", "use", "used", "due", "related", "instead", "associated" and similar
    words are weak, about 1.
Everything else is about 0. The activation depends only on the current token
(layer 0), so no carry is needed.
"""

READS = ()

STRONG = {"based": 9.5}

MEDIUM = {
    w: 2.0
    for w in [
        "depending", "depends", "depend", "dependent", "basis", "according",
        "基于", "基础上", "的基础上", "основе", "основан", "partir", "に基づ",
    ]
}

WEAK = {
    w: 1.0
    for w in [
        "using", "use", "uses", "used", "due", "related", "instead",
        "associated", "located", "driven", "focus", "focused",
    ]
}

