"""A mostly spelling-sensitive negative response to short 'po' pieces.

Complete words are not equivalent to the syllable: 'pol' is stronger than
'political', and 'pow' is unlike 'power'. A few longer po families retain
the response. Other cues include Cyrillic по, Japanese ポ, Korean 포,
and selected Chinese characters, especially 波 ('wave'). Closing </think>
is a separate negative cue. This token-only approximation omits most weak
background responses and context-dependent changes in strength.
"""
READS = ()

PO_PIECES = {
    'pol': -3.3,
    'pot': -2.1,
    'por': -1.5,
    'pow': -1.8,
    'pod': -1.0,
    'poi': -1.45,
    'pou': -1.2,
    'pom': -1.2,
    'poly': -0.85,
    'polym': -1.8,
}
CYRILLIC_PO = {
    'по': -2.2,
    'пол': -2.1,
    'пор': -1.5,
    'пот': -1.8,
    'пок': -1.1,
    'пов': -0.8,
    'пом': -0.6,
    'под': -0.25,
}


def response(token):
    s = token.strip()
    raw = s.lstrip('._/-(@')
    w = raw.lower()
    spaced = token[:1].isspace()
    if s == '</think>':
        return -1.0
    if s == '波':
        return -5.7
    if s == '坡':
        return -3.5
    if s in ('泊', '玻', '婆', '波动', '波特'):
        return -1.5
    if s == '一波':
        return -4.4
    if s == 'ポ':
        return -4.25
    if s == '포':
        return -3.35
    if s in ('诗', '诗歌', '诗人'):
        return -1.15
    if w in CYRILLIC_PO:
        return CYRILLIC_PO[w]
    if w.startswith('по'):
        return -0.35
    if w == 'po':
        if raw.isupper():
            return -3.1 if spaced else -3.5
        return -4.5 if spaced else -3.7
    if w == 'pon':
        return -1.9 if spaced else -2.9
    if w == 'pos':
        return -1.05 if spaced else -1.6
    if w in PO_PIECES:
        return PO_PIECES[w]
    if w in ('pu', 'пу'):
        return -1.15
    if len(w) <= 3 and w.endswith('po'):
        return -1.8
    if len(w) <= 5 and w.endswith('pol'):
        return -2.5

    # Repository is unlike report; bare repo is particularly strong.
    if w.startswith('repo') and not w.startswith('report'):
        if w == 'repo':
            return -3.0 if spaced or s != raw else -4.8
        return -1.85 if s != raw else -2.5
    if w.startswith('polynomial'):
        return -2.4
    if w.startswith('exponen') or w in ('ponent', 'ponents'):
        return -1.3
    if w == 'ponential':
        return -1.85
    if w.startswith('expos'):
        return -1.7 if w == 'exposure' else -1.1
    if w.startswith('potential'):
        return -1.7 if w.endswith('ly') else -0.95
    if w.startswith('powder'):
        return -1.4
    if w.startswith(('poem', 'poet')):
        return -1.15
    if w.startswith(('polic', 'poland', 'polar', 'polymer')):
        return -0.8
    if w in ('posed', 'poser', 'poses', 'posing'):
        return -0.9
    if w.startswith(('poor', 'poison', 'pover', 'pond')):
        return -0.85
    if w in ('opportunity', 'opportunities'):
        return -0.65
    if w in ('wave', 'waves'):
        return -1.0
    if 'po' in w:
        return -0.3 if len(w) <= 4 else -0.08
    return 0.0


def step(carry, prefix, upstream):
    return None, response(prefix.token_strings[-1])

