programs.sol:
"""A line-opening signal with several strong lexical responses.

The small background rises just after a line break and fades along the line;
it is suppressed near document starts. Digits, spacing and punctuation have
lower backgrounds than long word pieces. Strong positive spikes mark
'Alternatively', OBSERVATION and </think>; initial chat headers are negative.
These rules approximate the signal, rather than memorizing its vocabulary.
"""
import math

READS = ()


def background(s, age, line_age):
    word = s.strip()
    if word.isalpha():
        value = 0.006 if len(word) >= 5 else -0.001
    elif word.isdigit():
        value = -0.009
    elif not word:
        value = -0.012
    elif not any(c.isalnum() for c in word):
        value = -0.006
    elif any(c.isalpha() for c in word):
        value = -0.005
    else:
        value = 0.002
    value += 0.042 * math.exp(-line_age / 10)
    value -= 0.019 if line_age == 0 else 0.0
    value -= 0.028 * math.exp(-age / 45)
    return value


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        age, previous, tail, line, line_age = 0, '', '', '', 0
    else:
        _, age, previous, tail, line, line_age = carry
        age += 1

    value = background(s, age, line_age)
    if age == 0 and s.endswith('\n'):
        value = -0.17
    word = s.strip()
    if word.lower() == 'alternatively':
        value = 0.53 if s == 'Alternatively' else 0.49
        if word.islower():
            value = 0.26
    elif word.lower() == 'alternative':
        value = 0.26 if not s.startswith(' ') else 0.16
        if s.startswith(' ') and word[0].isupper():
            value = 0.21
    elif word.lower() in {'alternate', 'alternatives'}:
        value = 0.11
    elif s == '</think>':
        value = 0.42
    elif s == '<think>':
        value = 0.072
    elif (tail + s).endswith('OBSERVATION'):
        value = 0.49
    elif (tail + s).endswith('OBSERV'):
        value = 0.17
    elif s == '<|im_start|>':
        value = -0.346 if age == 0 else -0.005
    elif previous == '<|im_start|>':
        if age == 1:
            value = {'user': -0.579, 'system': -0.52,
                     'assistant': -0.499}.get(s, value)
        elif s == 'user':
            value = -0.025
        elif s == 'assistant':
            value = 0.004
    elif s == ' FIG':
        value = 0.19 if not line.strip() else 0.085
        if line.strip().startswith('[') and line.rstrip().endswith(']'):
            value = 0.16
    elif s == 'External':
        value = 0.13
    elif s == ' links':
        value = 0.315 if previous.strip() == 'External' else 0.09

    line = (line + s).rsplit('\n', 1)[-1][-80:]
    line_age = 0 if '\n' in s else line_age + 1
    return (doc, age, s, (tail + s)[-20:], line, line_age), float(value)

