programs.sol:
"""A limited text-level approximation of a weak, mixed component.

The clearest retained pattern is an unspaced i-initial fragment after a
short or capitalized fragment, especially 'tr'. Smaller terms describe
function words, quantity phrases, scripts, and document/chat markers.
This intentionally omits most token-specific variation; it is not a
complete semantic detector. State resets at every document boundary.
"""
READS = ()

ARTICLES = frozenset(('a', 'an', 'the'))
HAVE = frozenset(('have', 'has', 'had', 'having'))
FIRST_PERSON = frozenset(('i', 'me', 'we', 'us'))
OPPOSITION = frozenset(('against', 'despite', 'versus'))
QUANTITY = frozenset('''number numbers amount amounts quantity quantities
lot lots range some each every few many much several all any'''.split())


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    prior = previous.strip()
    value = 0.000573

    if token.startswith(('i', 'I')):
        value += 0.061952
        if prior.isupper():
            value -= 0.086941
        elif prior.istitle():
            value -= 0.041454
        elif prior.islower():
            value -= 0.038994
        if len(prior) == 1:
            value -= 0.044120
        elif len(prior) == 2:
            value -= 0.026390
        if token.startswith('I'):
            value -= 0.011927
        if len(word) <= 3:
            value -= 0.000602
        if prior.lower() == 'tr':
            value -= 0.142116
    if token.startswith(('j', 'J')):
        value -= 0.017186

    if lower in ARTICLES:
        value += 0.000206
        if not token.startswith(' '):
            value -= 0.008184
    if lower in HAVE:
        value -= 0.010657
    if lower in FIRST_PERSON:
        value -= 0.008921
    if lower in OPPOSITION:
        value -= 0.096356
    if word in ("'s", '’s'):
        value -= 0.014887
    if lower == 'and':
        value -= 0.005400
    if lower == 'of' and prior.lower() in QUANTITY:
        value -= 0.048629

    if token.startswith('ι'):  # Greek iota
        value += 0.124422
    if word == '的':  # Chinese attributive/possessive particle
        value += 0.046826
    if word == 'の':  # Japanese possessive particle
        value += 0.025821
    if any('\u0400' <= c <= '\u052f' for c in word):
        value += 0.014207
    if token.startswith('<|im_'):
        value -= 0.018568

    return (document, token), float(value)

"""A spelling-fragment feature: chiefly s at a within-word token boundary.

Short s-initial fragments following letters get a positive response.
Consonant clusters are strongest; vowels, repeated s, title case, and long
fragments weaken it. Cyrillic and Arabic s spellings have smaller versions
of the response. Document-initial '#' is a separate response.
The numbers are rounded fits to training activations, not token-ID scores.
"""

READS = ()
LATIN_VOWELS = frozenset('aeiouy')
CYRILLIC_VOWELS = frozenset('аеёиоуыэюя')
SIBILANTS = frozenset('sсшσςس')


def latin_strength(s):
    n = len(s)
    # An s merged with capitalized identifier material remains a fragment.
    if n > 2 and s[1].isupper() and not s.isupper():
        return 3.0
    if s[0].isupper() and not s.isupper():
        return 0.54 if n == 2 else 0.28 if n == 3 else 0.10
    if n == 1:
        return 0.89 if s.isupper() else 1.12
    if n == 2:
        c = s[1].lower()
        if c in LATIN_VOWELS:
            return 1.55
        if c in 'st':
            return 1.15
        if c in 'hk':
            return 1.89
        if c in 'lmn':
            return 2.63
        if c in 'bdg':
            return 3.0
        return 2.20
    if n == 3:
        return 0.85 if s.isupper() else 1.10
    return 0.76 if n == 4 else 0.43 if n == 5 else 0.30


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    start = (len(prefix.token_ids) == 1 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if start and s == '#':
        return None, 0.805
    stripped = s.lstrip(' ')
    if s != stripped and stripped.isascii() and stripped.isalpha():
        if stripped[:1].lower() == 's':
            if len(stripped) == 1:
                return None, -0.04
            if len(stripped) == 2 and stripped[1].lower() not in LATIN_VOWELS:
                return None, 0.05 if stripped[1].lower() == 'h' else 0.16
    if not s or not s.isalpha():
        return None, 0.0
    first, n = s[0].lower(), len(s)
    latin = s.isascii() and first == 's'
    if latin:
        base = latin_strength(s)
    elif first == 'с':
        base = 0.80 if n <= 2 else 0.62 if n == 3 else 0.50 if n == 4 else 0.36
    elif first == 'ш':
        base = 0.64 if n == 1 else 0.45 if n == 2 else 0.63 if n == 3 else 0.2
    elif first == 'س':
        base = 0.52 if n == 1 else 0.46 if n == 2 else 0.39 if n == 3 else 0.20
    else:
        return None, 0.0
    if start:
        return None, float(base * 0.7 if n > 1 else 0.0)
    previous = prefix.token_strings[-2]
    c = previous[-1:] if previous else ''
    lower = c.lower()
    if c.isalpha():
        if lower in SIBILANTS:
            base *= 0.15
        elif latin and lower in LATIN_VOWELS:
            base *= 0.65
        elif first == 'с' and lower in CYRILLIC_VOWELS:
            base *= 0.25
        elif first == 'ш' and lower in CYRILLIC_VOWELS:
            base = 0.0
        if latin and not c.isascii():
            base *= 0.60
        if s == 's' and c.isupper():
            base += 0.30
        if s == 'S' and c.islower():
            base *= 0.55
        return None, float(base)
    if c.isdigit():
        if n == 1:
            return None, 0.18 if s == 's' else 0.12
        return None, float(base * 0.36)
    if first in 'сш' and n == 1:
        return None, -0.15
    if n == 2 and latin and s[1].lower() not in 'aeiouyst':
        return None, 0.18 if c == '_' else -0.08
    return None, -0.04 if s[0].isupper() else 0.0

"""A token-local LEG/EG spelling feature, with a small anatomical overlap.

Bare leg and legs dominate. Longer LEG words, short EG syllables, and a few
leg/foot words in English, Chinese and Russian receive smaller positives.
This deliberately leaves unrelated lexical and contextual variation at zero.
"""
import unicodedata

READS = ()


def lexical_value(raw):
    text = raw.strip().strip('._/-()')
    capital = text[:1].isupper()
    spaced = raw[:1].isspace()
    lower = text.lower()
    word = ''.join(c for c in unicodedata.normalize('NFD', lower)
                   if not unicodedata.combining(c))
    if lower in {'lég', 'лег'}:
        return 2.6 if spaced else 2.35
    if word == 'leg':
        return (4.6 if capital else 5.1) if spaced else (4.9 if capital else 4.0)
    if word == 'legs':
        return 4.9 if capital else (4.4 if spaced else 4.1)
    if word in {'腿', '双腿'}:
        return 4.4
    if word.endswith('legged'):
        return 3.5
    if word == 'legacy' or word in {'deleg', 'illeg', 'legt', 'legation'}:
        return 2.3
    if word.startswith(('leg', 'eleg')):
        return 1.5
    if word.startswith(('illegal', 'delegat')):
        return 1.5 if word.startswith('delegation') else 0.9
    if word.startswith('alleg') and word != 'allegiance':
        return 0.6
    if word in {'colleg', 'coleg'}:
        return 1.3
    if word.startswith('segment'):
        return 0.6 if word.startswith('segmentation') else 1.3
    if word == 'seg':
        return 1.5 if capital else 1.0
    if word == 'eg' or lower == 'ег':
        return 1.15 if capital else (0.95 if spaced else 1.6)
    if word == 'neg':
        return 1.4 if spaced else 2.1
    if word.endswith('eg') and len(word) == 3:
        return 0.2 if word[0] in 'rbd' else 0.8
    if word in {'egg', 'eggs', 'egl', 'ego', 'mega', 'veget', 'vegan'}:
        return 0.65
    if word.startswith('negotiat') or word in {'regime', 'regiment', 'легко'}:
        return 0.6
    if word in {'大腿', 'thigh', 'ног'}:
        return 1.5
    if word in {'digit', 'digits', 'foot', 'thighs', '脚', '肢'}:
        return 0.7
    if word in {'feet', 'knee', 'knees', 'limb', 'limbs'}:
        return 0.45
    return 0.0


def step(carry, prefix, upstream):
    return None, float(lexical_value(prefix.token_strings[-1]))

programs.haiku:
"""Lower-limb "leg" detector (layers.0.mlp.down_proj, component 1620).

What it does: this component reads the current token and writes a signal
that is large when the token is the word "leg" (or its Chinese equivalent
腿), and smaller for other leg-spelled words and for other lower-limb words.
It does not look at context: the activation is almost a pure function of
the current token's spelling.

Predicted activation (for the token at this position, from its text alone):
  - "leg" as a body part: leg, legs, Leg, LEG, 腿, 双腿      -> about 4.7
  - other leg-spelled words in other languages (lég, ног)   -> about 2.0
  - leg-root words: legal, legislation, legend, legacy,
    legitimate, delegate, alleged ...                         -> about 1.5
  - short "eg" pieces: eg, EG, ég, seg-, neg, Seg           -> about 1.2
  - other lower-limb words: foot, feet, knee, thigh, 脚, 腳, 肢 -> about 0.6
  - digit / digits                                           -> about 0.7
  - everything else                                          -> 0
Words that only look like "leg" but are not (college, privilege,
telegram, allegiance) are excluded and predict 0.

Main idea: the component is a "leg" detector. Its value comes from the
word's meaning and spelling, not from what comes before it.
"""

import re

READS = ()

BODY_LEG = {"leg", "legs", "腿", "双腿"}
OTHER_LEG = {"lég", "ног", "thigh", "thighs", "лег"}
LIMB = {"foot", "feet", "knee", "knees", "limb", "limbs", "脚", "腳", "肢"}
SHORT_EG = {"eg", "ég", "neg", "seg", "seg.", "eg."}
DIGIT = {"digit", "digits", "-digit"}
NOT_LEG = re.compile(r"colleg|privileg|telegra|allegian")


def value_of(token):
    word = token.strip().lower()
    if word in BODY_LEG:
        return 4.7
    if word in OTHER_LEG:
        return 2.0
    if "leg" in word and not NOT_LEG.search(word):
        return 1.5
    if word in SHORT_EG or word.startswith("seg"):
        return 1.2
    if word in LIMB:
        return 0.6
    if word in DIGIT:
        return 0.7
    return 0.0


def step(carry, prefix, upstream):
    return None, value_of(prefix.token_strings[-1])

