    (1.05, {'explosive'}),
    (0.9, {'spark', 'sparks', 'flame', 'flames', '烧'}),
    (0.8, {'burned', 'burnt', 'flammable', 'ammable', '木', '土'}),
    (0.65, {'combustion', 'flaming', '激情', '燃烧', '爆', '炸'}),
