    if previous == 'congreg' and word == 'ational':
        return 0.4694
    if word in {'devotion', 'devotional'}:
        return 0.4716
    # Day, morning, evening, night or bedtime + an activity/study word.
    if (previous in {'日', '早', '晚', '夜', '晨', '睡前'}
            and word in {'班', '会', '會', '学', '學', '教',
