programs.sol:
"""A mostly chat-boundary component, with weaker alphabetic fragment signals.

End-of-message markers are strongly negative after tool blocks. Other message
endings depend on punctuation and the script of the last fragment. Role names
and newlines following chat/control markers are positive. Very short contexts
weaken some of these signals. Short Cyrillic, Arabic and Greek fragments are
positive at word/script boundaries, but near zero inside words.

The state contains just the previous token and position in the current document.
All magnitudes are approximations fitted to training examples; ordinary lexical
variation is deliberately omitted.
"""
import math
import unicodedata

READS = ()


def script_of(character):
    return unicodedata.name(character, '').partition(' ')[0]


def message_end(previous, position):
    if previous == '</tool_call>':
        return -4.71 + 3.4 / (1 + position / 2.5)
    if previous == '</tool_response>':
        return -4.23 + 1.43 * math.exp(-position / 9.5)
    if '\n' in previous:
        return 0.78
    if previous.endswith('。'):
        return 0.45
    if previous.endswith(('？', '؟')):
        return 0.25
    if previous.endswith('.'):
        return -0.04
    if previous.endswith('?'):
        return -0.53
    if previous.endswith('!'):
        return -0.68
    if previous.endswith('！'):
        return 0.1
    if not previous:
        return -2.15
    last = previous[-1]
    if last.isdigit():
        return -1.49
    if last.isalpha():
        script = script_of(last)
        if script in ('CYRILLIC', 'ARABIC'):
            return -3.0
        if script == 'LATIN':
            if previous[0].isspace():
                return -1.70
            return -2.15 + 0.16 * min(8, max(0, len(previous) - 4))
        return -1.85
    if last in '\"\'”’':
        if '?' in previous and last in '”’':
            return 0.2
        return -0.2 if '.' in previous or previous[0].isspace() else -1.30
    if last in ')]}':
        return -0.2 if '.' in previous else -1.0
    if last in ':;':
        return -0.3
    if last == '`':
        return -0.65
    if unicodedata.category(last) in ('So', 'Mn'):
        return -0.25
    return -1.3


def fragment_signal(token, previous):
    if not token or not previous or not token[0].isalpha():
        return 0.0
    script = script_of(token[0])
    if script not in ('CYRILLIC', 'ARABIC', 'GREEK'):
        return 0.0
    last = previous[-1]
    if ((last.isalpha() and script == script_of(last))
            or unicodedata.category(last).startswith('M')):
        return -0.03 if len(token) < 3 else 0.0
    if last == '\ufffd':
        return 0.0  # A partial UTF-8 character is not a known word boundary.
    if script == 'CYRILLIC':
        value = 0.20 if token[0].isupper() else 0.65
        return value * 0.55 if len(token) >= 3 else value
    if script == 'ARABIC':
        if len(token) >= 3 or (last.isspace() and '\n' not in previous):
            return 0.35
        return 0.9 if len(token) == 1 else 0.65
    return 0.15


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1], carry[2]
    token = prefix.token_strings[-1]
    value = 0.0
    if token == '<|im_end|>':
        value = message_end(previous, position)
    elif token == '<|im_start|>':
        value = -0.90 if position == 0 else -0.03
    elif previous == '<|im_start|>':
        if token == 'assistant':
            value = 1.07
        elif token == 'user':
            value = 0.44 if position == 1 else 0.963 - 0.518 / (1 + position / 8)
    elif token in ('\n', '\n\n'):
        value = -0.03 if token == '\n' else -0.01
        if previous == '<|im_end|>':
            value = 1.175 - 0.34 * math.exp(-position / 2.5)
        elif previous == 'assistant':
            value = 0.39
        elif previous in ('<tool_call>', '<tool_response>'):
            value = 0.85
        elif previous in ('<think>', '</think>'):
            value = 0.95
    elif token == '<tool_call>':
        if position == 0:
            value = -1.99
        else:
            value = 0.52 if previous == '\n' else 0.65
            if '\n' not in previous:
                value = -0.35
    elif token == '</tool_call>':
        value = -0.20 if '"' in previous else 0.02
        if position == 0:
            value = -1.56
        elif previous == '<tool_call>':
            value = -2.62
    elif token == '</tool_response>':
        if '\t' in previous:
            value = -0.49 if previous.count('\n') < 3 else -1.63
        elif '.' in previous:
            value = 0.02
        elif previous == '\n\n':
            value = -0.12
        else:
            value = -0.24
    elif token in ('<think>', '</think>'):
        value = 0.09 if token == '<think>' else 0.16
    elif (token == 'O' and previous == '\n' and position >= 2
          and prefix.token_strings[-3] == '<tool_response>'):
        value = 0.58  # Initial letter of the conventional OBSERVATION label.
    else:
        value = fragment_signal(token, previous)
    return (doc, position + 1, token), float(value)

