                i >= 2
                and prefix.document_ids[i] == prefix.document_ids[i - 2]
                and prefix.token_strings[i - 2] == "<|endoftext|>"
            ):
                return None, 0.44
            return None, 0.93

    if token == "\n":
        if previous == "<|im_end|>":
            return None, 1.12
        if previous in ("<tool_call>", "<tool_response>"):
            return None, 0.86
        if previous == "assistant":
