"""Approximate page-label, section-heading and message-boundary responses.

Training examples show large negative responses around page metadata and headings.
Capitalized layout labels receive a negative signal, especially at line starts.
Smaller offsets capture a few grammatical word classes. A one-token carry extends
label responses onto whitespace and recognizes tool-message closing sequences.
This is a coarse approximation, not a general semantic interpretation of every
small activation.
"""
from math import exp

READS = ()

PAGE_LABELS = set('''posts posted author authors editor category related follow
    followers joined advertisement copyright published download full free
    today last home search online comments replies views rating'''.split())
SECTION_LABELS = set('''abstract introduction summary contents references
    bibliography appendix background description lesson chapter'''.split())
CALENDAR_LABELS = set('''monday tuesday wednesday thursday friday saturday sunday
    january february march april may june july august september october november
    december'''.split())
NEWS_LABELS = {'记者', '网址', '正文', '作者', '编辑', '来源'}
POSSIBILITY = {'may', 'might', 'could', 'possible', 'potential', 'maybe'}
QUANTITY = {'many', 'few', 'every', 'most', 'per', 'range', 'sum'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position, previous_label = '', 0, 0.0
    else:
        _, previous, position, previous_label = carry
    s = prefix.token_strings[-1]
    word = s.strip()
    low = word.lower()
    line_start = position == 0 or previous.endswith('\n')
    capitalized = word[:1].isupper()
    value = 0.003

    # Layout cues are strongest near the beginning of a document.
    early = exp(-position / 35.0)
    label = 0.0
    if capitalized and low in PAGE_LABELS:
        label -= 0.055 + line_start * (0.08 + 0.12 * early)
    if capitalized and low in SECTION_LABELS:
        label -= 0.045 + line_start * (0.025 + 0.14 * early)
        if previous.count('\n') >= 3:
            label += 0.055
    if capitalized and low in CALENDAR_LABELS and not s.startswith(' '):
        label -= 0.055 + line_start * 0.08 * early
    if word == 'Abstract':
        label = -0.12 - line_start * (0.17 + 0.07 * early)
    if word == '本报讯':
        label = -0.65
    elif word in {'日讯', '日电'}:
        label = -0.28
    elif word in NEWS_LABELS:
        label = -0.07 - 0.08 * line_start
        if word == '网址':
            label -= 0.10
    value += label

    if word in {'##', '###'}:
        value += -0.015 - 0.25 * early if previous.endswith('\n') else 0.01
    if low in POSSIBILITY:
        value += 0.037
    if low in QUANTITY:
        value += 0.044
    if low in {'because', 'despite', 'without'}:
        value += 0.044
    if low in {'they', 'them', 'us'}:
        value += 0.032
    if low == 'our':
        value -= 0.053
    if low in {'just', 'only', 'furthermore'}:
        value -= 0.035
    if low in {'within', 'along', 'beyond'}:
        value -= 0.036
    if low == 'you' and word == 'you':
        value -= 0.019
    if low == 'or':
        value += 0.014
    if low == 'before':
        value += 0.036

    prev_word = previous.strip()
    if not word or word in {':', '：'}:
        value += 0.45 * previous_label
    if s == ' to' and prev_word.lower() in {'subject', 'addition'}:
        value -= 0.13
