        elif prev_word.lower() in {'amount', 'amounts', 'piece', 'couple',
                                    'cup', 'pair', 'form', 'end', 'middle',
                                    'lack', 'result', 'results'}:
            value -= 0.075
    if s == ' to':
        if prev_word.lower() == 'how':
            value -= 0.08
        elif prev_word.lower() in {'have', 'has', 'had', 'able'}:
            value -= 0.045
        elif prev_word.lower() in {'need', 'try', 'trying', 'tries', 'want',
                                    'ready', 'designed', 'set'}:
            value += 0.029
        elif prev_word.lower() in {'related', 'adjacent', 'prior', 'next',
                                    'entitled', 'limited', 'exposed'}:
            value -= 0.060
    if word.isdigit():
        value -= 0.005
    if s == '\n\n':
        value -= 0.02
    if word in {'/workspace', '/node', '/src'}:
        value -= 0.08
    if word in {'<think>', '</think>'}:
        value = 0.045
    if word == 'user' and previous == '<|im_start|>':
        value = 0.04
    if word == '<|endoftext|>':
        value = 0.018
    if word == '<tool_call>':
        value = -0.14
    elif word == '</tool_call>':
        value = 0.05
    elif word == '</tool_response>':
        value = 0.13
    elif word == '<|im_end|>':
        if prev_word == '</tool_response>':
            value = -0.135
        elif prev_word == '</tool_call>':
            value = -0.060
        else:
            value = 0.115 if prev_word.endswith(('.', '?', '!', '。', '？')) else 0.07
