def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    previous = prefix.token_strings[-2] if same_doc else ""
    bare = word.strip()
    line_start = "\n" in previous
    value = BASELINE
    if bare in METADATA_LABELS:
        value += -0.08
    elif word == "<tool_call>":
        value += -0.14
    elif word == "</tool_response>":
        value += 0.13
    elif word.startswith(" ") and bare.islower() and bare.isalpha() and bare not in FUNCTION_WORDS:
        value += 0.0035
    if line_start and (bare[:1].isupper() or bare.isdigit()):
