        elif word in ('=', '+=', '-=', '*=', '/='):
            value = 0.50
        elif word in ('==', '===', '!=', '!==', ':='):
            value = 1.0
        elif word in ('->', '=>', '→', '<<', '>>', '::', '://'):
            value = 1.15
        elif word in ('//', '///', '/*', '*/'):
            value = 0.8
        elif word.startswith('#'):
            value = 0.95
        elif word == '\\':
            value = 0.7
        elif word == '_':
            value = 0.85
        elif word.startswith('{'):
            value = 0.65
        elif word.startswith('$'):
            value = 0.55
        elif word in ('··', '・'):
            value = 2.2
        elif '\x00' in word:
            value = 1.4
        elif word in ('"', '“', '”', "'") and spaced:
            value = 0.65
        elif word in ('**', '*', '`') and spaced:
            value = 0.45
    else:
        value = 0.5 * continuing
        if lower in FUNCTION_WORDS:
            value += -0.10 if spaced else -0.05
        elif word.isascii() and word.isalpha():
