            if spaced and lower.endswith(('ed', 'ing', 'ly')):
                value -= 0.27
            if not spaced and lower.endswith('ed'):
                value += 0.18
            if lower in DECLARATIONS:
                value += 0.5
            if lower in ('import', 'include', 'package', 'namespace'):
                value += 0.6
            if lower in ('then', 'else', 'because'):
                value += 0.5
