            elif any('\uac00' <= c <= '\ud7a3' for c in word):  # Korean
                value += 0.8
            elif any('\u0600' <= c <= '\u06ff' for c in word):  # Arabic
                value += 0.4 if spaced else 0.6
            # Latin letters with accents or other diacritics.
