           'overline', 'underline', 'dot', 'ddot', 'overrightarrow'}
FONTS = {'mathrm', 'mathbf', 'mathbb', 'mathcal', 'mathit', 'mathsf',
         'mathtt', 'mathscr', 'mathnormal', 'bm', 'rm', 'bf', 'it'}
LABELS = {'label', 'ref', 'eqref', 'cite', 'section', 'subsection',
          'caption', 'color', 'multicolumn', 'begin'}

