SYNTAX = {
    '][': -0.226,
    ')(': -0.108,
    '//': -0.055,
    '--': -0.055,
    '}}': -0.05,
    '#': 0.05,
    '_': -0.018,
    '[': 0.025,
    '["': 0.07,
    "['": 0.07,
    '[\\': 0.07,
    '\\[': 0.065,
    '\\\\': 0.065,
    '\\n': 0.023,
    '\\t': 0.023,
    '\\r': 0.023,
    '<tool_response>': 0.10,
    '</think>': 0.10,
    '</tool_response>': -0.05,
    '</tool_call>': -0.05,
    '<tool_call>': 0.05,
    '<think>': 0.05,
}


def opening(token, history):
    before, _, after = token.strip().partition('{')
    previous = history.rstrip()
    spaced = token.startswith((' ', '\t'))
    if '_' in before:
        return -0.576
    if '^' in before:
        return -0.415 if after == '-' else -0.516
    if '$' in before:
        return -0.44 if '"' in before else -0.72
    if '\n' in token or '\r' in token:
        return -0.10 if ')' in before else 0.01
    if after.startswith(('"', "'")):
        return 0.0 if spaced else 0.04
    if after not in ('', '\\', '-', '{'):
        return -0.06 if '}' in after else -0.10
    if before:
        if before.endswith(('}', ']')):
            return -0.38
        if '"' in before or "'" in before:
            return -0.20 if spaced else -0.31
        if before == '(':
            return -0.16
        return -0.24 if before == ')' else -0.22
    if after == '{':
        return -0.56 if previous.endswith(('_', '^')) else -0.23
