        value = -0.77 if previous.endswith('^') else -0.66
        return value + (0.07 if after == '\\' else 0.0)
    if previous.endswith('}'):
        return -0.34 if after == '\\' else -0.30
    if spaced:
        return -0.11 if after == '\\' else -0.04
    command = re.search(r'\\([A-Za-z]+)$', previous)
    name = command.group(1) if command else ''
    value = -0.10 if previous else 0.0
    if name in FRACTIONS or name == 'sqrt':
        value = -0.025
    elif name in ACCENTS:
        value = -0.23
    elif name in FONTS:
        value = -0.09
    elif name in LABELS:
        value = 0.08
    elif name == 'end':
        value = -0.12
    elif name in {'text', 'operatorname', 'mbox', 'hbox', 'boxed'}:
        value = 0.02
