"""Score phrases about what someone can, will, or needs to do.

The strongest signal is a modal immediately after 'you'. A weaker signal
continues into a few grammatical complements (need to, will see, be able).
Requests such as 'you provide' and 'help me' have the opposite sign.
Contractions and several non-English ability expressions are included.
All other tokens get zero. The carry remembers just two tokens and the last
phrase score, and resets at document boundaries. This is a lexical phrase
recognizer, not a general semantic parser.
"""
READS = ()

# Ordinary use versus use immediately after the second-person pronoun.
MODALS = {
    'can': (0.77, 4.33),
    'will': (0.00, 4.06),
    'may': (0.00, 3.74),
    'should': (-0.06, 3.76),
    'might': (-0.07, 3.52),
    'could': (0.15, 2.21),
    'would': (-0.07, 2.79),
    'must': (-0.06, 2.00),
    'cannot': (0.10, 1.80),
}
FUTURE = {'will', "'ll"}
PERCEPTION = {'see', 'find', 'know', 'notice', 'discover'}
# Familiar translations of ability expressions, rather than token-id exceptions.
ABILITY = {
    'kann': 0.44,
    'können': 0.44,
    'kan': 0.29,
    'puede': 0.63,
    'pode': 0.69,
    'يمكن': 0.83,
    'можно': 0.58,
    'puedes': 1.2,
    'kunt': 0.95,
    'можете': 1.6,
    'pouvez': 3.45,
}
REQUESTS = {'help', 'give', 'tell', 'provide', 'show', 'explain', 'send'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    at_start = carry is None or carry[0] != doc
    if at_start:
        previous, earlier, last_value = '', '', 0.0
    else:
        _, previous, earlier, last_value = carry
    raw = prefix.token_strings[-1]
    token = raw.strip().replace('’', "'")
    word = token.lower()
    before = previous.lower()
    addressed = before == 'you'
    you_before_previous = earlier.lower() == 'you'
    modal_before = before in MODALS or before in FUTURE
    positive = max(0.0, last_value)
    # Do not confuse a suffix such as 'able' in 'variable' with a word.
    word_start = (not previous or raw[:1].isspace()
                  or not previous[-1:].isalnum())
    value = 0.0

    if word in {"'ll", "'d"}:
        value = (4.9 if word.endswith('ll') else 2.6) if addressed else 0.0
        if before == 'we' and word.endswith('ll'):
            value = 0.7
    elif word in {"'re", "'ve"}:
        value = 1.3 * positive - 0.15 if addressed else 0.05
    elif word == "'t":
        value = 1.0 if you_before_previous else (0.4 if before == 'won' else 0.0)
    elif '可以' in word and len(word) <= 7:
        value = 0.85
    elif word in {'できます', 'ことができます', 'することができます'}:
        value = 0.8
    elif word_start:
        if word in ABILITY:
            value = ABILITY[word]
        elif word in MODALS:
            ordinary, second_person = MODALS[word]
            value = second_person if addressed else ordinary
            if addressed and previous == 'You':
                value += 0.65
        elif word == 'you':
            if before in {'if', 'whether', 'can', 'could', 'would', 'should', 'will'}:
                value = 1.0
            elif before == 'when':
                value = 0.45
            elif at_start:
                value = 1.8 if token == 'You' else 1.0
            else:
                value = -0.05
        elif word == 'need':
            if addressed:
                value = 2.2
            elif before in FUTURE:
                value = 0.65 + 0.82 * positive
            elif before in MODALS or before in {"'t", 'not', 'also'}:
                value = 0.4 + 0.45 * positive
            else:
                value = 0.15 if before == 'we' else -0.1
        elif word == 'want':
            value = 1.1 if addressed else 0.15
            if modal_before:
                value = 0.7 + 0.65 * positive
        elif word in PERCEPTION:
            value = 0.9 if addressed else (0.15 if word == 'find' else 0.0)
            if modal_before:
                value = 0.5 + (0.8 if before in FUTURE else 0.5) * positive
        elif word == 'get':
            value = 0.65 if addressed else 0.0
            if modal_before:
                value = 0.1 + 0.45 * positive
        elif word == 'to':
            if addressed:
                value = 1.0
            elif before == 'need':
                value = min(2.6, 0.4 + 0.72 * positive)
            elif before in {'want', 'have', 'able', 'going', 'wish', 'expect'}:
                value = 0.25 + 0.65 * positive
                if you_before_previous and before in {'have', 'going', 'expect'}:
                    value = 1.3
        elif word == 'be':
            if before in FUTURE:
                value = 0.2 + 0.5 * positive
            elif you_before_previous and before in MODALS:
                value = 1.0
        elif word == 'have':
            if modal_before:
                value = 0.1 + (0.15 if before == 'can' else 0.5) * positive
        elif word == 'able':
            value = 1.25 + 0.9 * positive if before == 'be' else 0.65
        elif word == 'probably':
            value = 2.8 if addressed else 0.0
            if modal_before:
                value = 0.6 + 0.6 * positive
        elif word in {'also', 'easily', 'already'}:
            value = 1.0 if you_before_previous else 0.0
        elif addressed and word in {'say', 'mean', 'provide', 'recommend'}:
            value = -2.6
        elif addressed and word in {'give', 'tell'}:
            value = -1.2
        elif word == 'me':
            value = -0.1
            if before in REQUESTS:
                value = -2.1 if you_before_previous else -0.6
    return (doc, token, previous, float(value)), float(value)

