READS = ()


def step(carry, prefix, upstream):
    end = prefix.position
    tokens = prefix.token_strings
    docs = prefix.document_ids
    current = tokens[end].strip().lower()
    same_document = end > 0 and docs[end - 1] == docs[end]
    previous = tokens[end - 1].strip().lower() if same_document else ""
    same_before = same_document and end > 1 and docs[end - 2] == docs[end]
    before = tokens[end - 2].strip().lower() if same_before else ""

    if current == "can" and previous == "you":
        return None, 4.15
    if current == "can":
        return None, 0.65
    if current in ("kunne", "可", "均可"):
        return None, 0.5
    if current == "you" and previous in ("when", "if", "would"):
        return None, 0.75
    if current == "need" and previous == "you":
        return None, 2.5
    if current == "might" and previous == "you":
        return None, 3.6
    if current == "want" and previous == "you":
        return None, 1.8
    if current == "find" and previous == "you":
        return None, 0.8
    if current == "get" and previous == "you":
        return None, 0.9
    if current == "to" and previous == "you":
        return None, 1.3
    if current == "likely" and previous == "will":
        return None, 1.0
    if current == "will" and previous == "we":
        return None, 0.43
    if current == "able" and previous == "be":
        return None, 0.75
    if current == "recommend" and previous == "you" and before == "do":
        return None, -2.6
    if current == "me" and previous == "help":
        return None, -2.7
    if current in ("'ve", "’ve") and previous == "you":
        return None, -0.85
    if current == "to" and previous == "need" and before == "you":
        return None, 2.1
    if current == "to" and previous == "need":
        return None, 0.45
    return None, 0.0

"""Mark “of,” especially after common abstract-noun endings."""
READS = ()

STRONG_NOUN_ENDINGS = ("tion", "sion", "ment", "ing")
OTHER_NOUN_ENDINGS = ("ity", "ance", "ence", "ness")
RELATION_WORDS = {"between": 0.9, "de": 0.38, "von": 0.38, "des": 0.31, "di": 0.20}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous_word = ""
    if carry is not None and carry[0] == document:
        previous_word = carry[1]

    token = prefix.token_strings[-1]
    piece = token.strip().lower()
    value = 0.0
    at_word_start = token[:1].isspace() or not previous_word

    if at_word_start and piece in RELATION_WORDS:
        value = RELATION_WORDS[piece]
    if piece == "of" and at_word_start:
        noun = previous_word.lower().rstrip(".,:;!?)]}\"'")
        if noun.endswith(STRONG_NOUN_ENDINGS):
            value = 2.4
        elif noun.endswith(OTHER_NOUN_ENDINGS):
            value = 1.15
        else:
            value = 0.4

    if token[:1].isspace():
        current_word = piece[-16:]
    else:
        current_word = (previous_word + token)[-16:]
    return (document, current_word), value

programs.sol:
"""Approximate a response to possibilities and the consequences actions enable.

The main triggers are modal auxiliaries, consequence connectives, and verbs
of helping or producing outcomes. Impersonal/relative subjects strengthen
modals; personal subjects weaken them. Recent modals strengthen enabling
verbs, including across a short adverb sequence. Commas and "and" strengthen
"so", "then", and "thus". Case and token-boundary corrections are small.

Selected translations cover similar cause, purpose, and outcome expressions.
Unrecognized tokens get a tiny baseline: these rules explain characteristic
triggers, not the component's fine token-specific background variation.
"""
READS = ()

# Weakly responding verbs whose objects are produced or affected outcomes.
OUTCOME_VERBS = frozenset(
    "make give provide bring result cause ensure improve prevent increase "
    "influence impact create yield".split())
SUPPORT_VERBS = frozenset("assist aid enhance enable facilitate guide minimize".split())
INTERVENING_ADVERBS = frozenset(
    "also not only even easily further then potentially significantly "
    "certainly inadvertently indirectly greatly better".split())

MODALS = {
    'can': 0.54, 'would': 0.60, 'may': 0.66, 'will': 0.48,
    'could': 0.44, 'might': 0.27, 'shall': 0.34, 'must': 0.18,
    'cannot': 0.23,
}
CONSEQUENCE = {
    'so': 0.55, 'then': 0.47, 'thus': 0.76, 'therefore': 0.72,
    'hence': 0.87, 'thereby': 1.75, 'consequently': 0.71,
    'otherwise': 0.39, 'accordingly': 0.37, 'hereby': 0.36,
}
ENABLING = {
    'help': 0.44, 'helps': 0.47, 'helped': 0.57, 'helping': 0.40,
    'allow': 0.42, 'allows': 0.31, 'allowed': 0.34, 'allowing': 0.45,
    'lead': 0.37, 'leads': 0.11, 'led': 0.19, 'leading': 0.43,
    'reduce': 0.32, 'reducing': 0.31, 'resulting': 0.38,
    'affect': 0.16, 'contribute': 0.11, 'suggesting': 0.03,
}
OUTCOME_ADVERBS = {
    'eventually': 0.75, 'ultimately': 0.76, 'later': 0.36,
    'further': 0.38, 'finally': 0.32, 'subsequently': 0.45,
    'greatly': 0.68, 'significantly': 0.39, 'potentially': 0.64,
    'possibly': 0.27, 'hopefully': 0.56, 'indirectly': 0.60,
    'inadvertently': 0.77, 'better': 0.0,
}
SUBJECT_ADJUSTMENT = {
    'i': -0.21, 'we': -0.21, 'you': -0.16,
    'he': -0.12, 'she': -0.12, 'they': -0.02,
    'it': 0.17, 'this': 0.47, 'that': 0.42, 'which': 0.64,
    'how': 0.21, 'what': 0.21, 'why': 0.21,
}
MODAL_BOOST = {
    'can': 2.10, 'could': 1.33, 'may': 1.18,
    'will': 1.48, 'would': 0.93, 'might': 0.68,
}

# Prefix matching includes Chinese tokens that fuse a marker with its object.
CHINESE_MARKERS = (
    (3.25, ('从而',)),                 # thereby
    (2.20, ('进而',)),                 # in turn
    (1.70, ('以便', '以免')),          # in order to; lest
    (1.30, ('以此',)),                 # by this means
    (1.55, ('同时也',)),               # also, at the same time
    (1.40, ('有助于', '有利于', '使其', '使之', '使我', '促使', '致使')),
    (1.30, ('更好地', '否则', '否則', '不然')),
    (1.25, ('可以帮助', '可以使', '会使')),
    (1.20, ('大大', '极大', '最大限度', '最大程度')),  # greatly; maximally
    (0.95, ('才能',)),
    (0.85, ('所以', '因此', '因而', '于是', '於是', '反而',
            '然后', '然後')),
    (0.75, ('帮助', '幫助')),
    (0.60, ('进一步', '同时', '共同', '最后', '最终', '之后',
            '之後', '以后')),
    (0.40, ('可以', '能够', '能夠', '更能', '就可以')),
)
CHINESE_OUTCOME_VERBS = (
    '降低', '减少', '減少', '导致', '導致', '促进', '促進',
    '确保', '確保', '避免', '方便', '提高', '影响',
)
CHINESE_MEANS = ('通过', '通過')
CHINESE_SIMPLE = {
    '使': 1.0, '使得': 0.95, '则': 0.82, '則': 0.90, '故': 0.80,
    '让': 0.58, '讓': 0.63, '后': 0.81, '後': 0.73, '后的': 0.65,
    '以': 0.43, '为': 0.32, '為': 0.28, '那么': 0.70,
}
CHINESE_MODAL_CONTEXT = ('可以', '能够', '能夠', '能', '可', '从而', '以')
TRANSLATIONS = {
    'ので': 0.98, 'なので': 0.74, 'ないので': 0.89,
    'によって': 0.66, 'により': 0.80, 'なら': 0.40, 'れば': 0.42,
    'чтобы': 0.43, 'может': 0.30, 'поэтому': 0.74, 'тогда': 0.63,
    'peut': 0.25, 'peuvent': 0.35, 'ainsi': 0.35, 'afin': 0.59,
    'alors': 0.39, 'donc': 0.31, 'kann': 0.22, 'dann': 0.27,
}


def foreign_response(text, previous):
    marker = text.lstrip('，,')
    if marker in CHINESE_SIMPLE:
        return CHINESE_SIMPLE[marker]
    if marker.startswith(('让', '讓')):
        return 0.65
    for value, starts in CHINESE_MARKERS:
        if marker.startswith(starts):
            return value
    if marker.startswith(CHINESE_OUTCOME_VERBS):
        return 0.5 + 0.4 * previous.startswith(CHINESE_MODAL_CONTEXT)
    if marker.startswith(CHINESE_MEANS):
        return 0.35 + 0.45 * previous.startswith(CHINESE_MODAL_CONTEXT)
    if marker.startswith(('позвол', 'помог', 'ayud')):
        return 0.65                # Russian allow/help; Spanish help.
    return TRANSLATIONS.get(text, -0.002)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', '', 0)
    _, previous, modal, age = carry
    raw = prefix.token_strings[-1]
    text, prev = raw.strip(), previous.strip().lower()
    word = text.lower()
    boost = MODAL_BOOST.get(modal, 0.0) * (0.65 if age > 1 else 1.0)
    capital = text != word
    joined = not raw.startswith(' ')
    value = -0.002

    if word in MODALS:
        value = MODALS[word] + SUBJECT_ADJUSTMENT.get(prev, 0.0)
        value -= 0.11 * capital + 0.15 * joined
        if word == 'will' and prev in ('i', 'we'):
            value -= 0.20
        if previous.strip() == 'This':
            value += 0.25
        if text == 'May':                 # Usually the calendar month.
            value = 0.12
    elif word in CONSEQUENCE:
        value = CONSEQUENCE[word] - 0.04 * capital - 0.07 * joined
        if word in ('so', 'then', 'thus'):
            if ',' in previous and '\n' not in previous:
                value += 0.29
            if prev == 'and':
                value += 0.22
            if prev in ('is', 'are', 'was', 'were', 'be', 'been', "'s"):
                value -= 0.11
            if prev in MODALS:
                value += 0.43
        if word == 'so' and capital:
            value += 0.20
        if word == 'then' and prev in ('since', 'until', 'by'):
            value -= 0.19
    elif word in ENABLING:
        value = ENABLING[word] - 0.09 * capital - 0.16 * joined
        strength = 1.0 if word == 'help' else (
            0.6 if word in ('allow', 'lead') else 0.35)
        value += strength * boost
        if prev in ('this', 'that', 'which'):
            value += 0.25
        if previous.strip() == 'This':
            value += 0.34
        if prev in ('the', 'a', 'an', 'some', 'of', 'your', 'need'):
            value -= 0.23
        if ',' in previous and word.endswith('ing'):
            value += 0.45
    elif word in OUTCOME_ADVERBS:
        value = OUTCOME_ADVERBS[word] - 0.10 * (capital or joined)
        if word != 'later':
            value += 0.45 * boost
    elif word in OUTCOME_VERBS or word in SUPPORT_VERBS:
        value = 0.20 if word in SUPPORT_VERBS else 0.04
        value += (0.40 if word in SUPPORT_VERBS else 0.30) * boost
        if capital or joined:
            value *= 0.5
    elif word == 'also':
        value = 0.24 * boost
        if prev in ('and', 'but') or ',' in previous:
            value += 0.14
    elif word == 'have' and modal:
        value = 0.13 * boost
    elif word == 'be':
        value = -0.22 if modal == 'will' else -0.16 if modal == 'may' else (
            -0.08 if modal else 0.0)
    else:
        value = foreign_response(text, previous.strip())
    if word in MODAL_BOOST and text == word:
        modal, age = word, 1
    elif word in INTERVENING_ADVERBS and age < 3:
        age += 1
    else:
        modal, age = '', 0
    return (document, raw, modal, age), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:1637 - a "setting up an effect" detector.

It fires on the words that introduce what something does or causes: result connectives
('thus', 'therefore', 'so', 'then', 'thereby', 从而, 因此, ので), modal verbs of ability or
possibility ('can', 'may', 'will', 'would', 'could'), and the verb or adverb right after such
a modal, which names the effect ('can help', 'will lead to', 'may reduce', 'can eventually').
