    elif current == "you" and "thank" in previous[-3:]:
        value = -0.78
    elif current == "much" and "thank" in previous[-4:]:
        value = -0.82
    elif current == "helps" and any(word in previous[-5:] for word in ("hope", "hopes")):
        value = -0.82
    elif current == "improve" and "help" in previous[-3:] and "you" in previous[-3:]:
        value = -0.65
    elif current == "hope":
        value = 0.25
    elif current == "reason" and any(
        word in previous[-4:] for word in ("good", "compelling")
    ):
        value = 0.55
    elif current == "odds" and "better" in previous[-3:]:
        value = 0.45

    history = (previous + (current,))[-8:]
    return (doc, history), float(value * 0.58)

"""Conservatively estimate a response to capitalized name-like phrases."""
READS = ()

NAME_CUES = {
    'in', 'at', 'from', 'of', 'the', 'a', 'near', 'to', 'by',
    'new', 'united', 'north', 'south', 'east', 'west', 'royal',
    'city', 'county', 'state', 'president', 'mr', 'mrs', 'dr',
}

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lstrip()
    if not token or not token[0].isupper():
        return None, 0.0
    previous = ''
    if (len(prefix.token_strings) > 1
            and prefix.document_ids[-2] == prefix.document_ids[-1]):
        previous = prefix.token_strings[-2].strip().lower()
    if any(ch.isalpha() for ch in token):
        strength = 0.65 if previous in NAME_CUES else 0.2
    else:
        strength = 0.4
    return None, 0.28 * strength

programs.sol:
"""Positive responses to Latin spellings of Chinese names and name-like syllables.

Recognize familiar name syllables, country/place labels, and phonetic endings
that complete a syllable begun in the previous token. A few neighboring East
Asian name forms are included too. Downweight acronyms and
spellings common as ordinary word fragments. Consecutive strong matches get a
small reinforcement. This is a spelling detector, not a determination of a
person's identity: unrelated words can contain the same pieces.
Strengths are approximate fits to training activations. Small background
fluctuations and negative responses are intentionally not modeled.
"""
import re

READS = ()

# Shared strengths for familiar Mandarin surname/given-name syllables.
NAME_GROUPS = (
    (0.5,
     'long min bo bi chun du fan he jun ma mo nan pan ren su'
    ),
    (0.9,
     'lei chi chu gu hu hou lin lu meng peng ping song sun tan wan ye'
    ),
    (1.6,
     'ling ming pang shan ting zhi zi hua bao kai mei tai tao bai dai deng '
     'ding fang fu han kang kong ning shi tang tong wen xi yi yun'
    ),
    (2.3,
     'xing heng quan yue hong chen dong gong hao huang ji jin li liu mao qi '
     'qin shen wei xin yan yao yin ying yong yu'
    ),
    (3.2,
     'qing wu chang feng guang jian luo wang xia xu yang yuan zhang zhao'
    ),
    (4.0,
     'cheng jiang jing tian xiao zheng zhou zhu'
    ),
)
NAMES = {w: a for a, words in NAME_GROUPS for w in words.split()}

# Spellings frequently encountered as ordinary word pieces.
COMMON_FRAGMENTS = set((
    'bi bo chen chi ding du fan gu han he ji lei li lin ling long lu ma mei min '
    'ming mo nan ning pan peng ping ren shi song sun tan tang tong wen xi xin yan '
    'ye yin ying yun zhi zi'
).split())

REGION_WORDS = set((
    'china chinese taiwan taiwanese'
).split())
CHINESE_PLACES = set((
    'anhui beijing changsha chengdu chongqing dalian fujian fuzhou guangdong '
    'guangxi guangzhou guilin guizhou hainan hangzhou harbin hebei heilongjiang '
    'henan hubei hunan jiangsu jiangxi jilin kunming liaoning nanchang nanjing '
    'nanning qingdao shaanxi shandong shanghai shanxi shenzhen sichuan suzhou '
    'taipei tianjin wuhan xiamen xian yunnan zhejiang zhengzhou'
).split())
OTHER_NAME_FORMS = set((
    'chan cheung chiang kwok leung ng tsang wong'
).split())

# Retroflex, palatal/legacy, other salient, and ordinary consonant initials.
INITIAL_CLASS = {
    initial: group
    for group, spellings in enumerate((
        "sh zh", "j q x ts hs", "ch z y w h", "b p m f d t n l g k r c s"
    ))
    for initial in spellings.split()
}
INITIAL_CLASS[""] = 3

# Four onset-class strengths, then the strength of an unattached final.
# These are spelling families used in Mandarin and related romanizations.
FINAL_FAMILIES = {
    'a e o': (-0.09, -0.1, -0.04, -0.03, 0.0),
    'i u': (0.9, 0.2, 0.38, -0.08, -0.01),
    'ai ei': (0.47, 0.41, 0.55, 0.03, 0.05),
    'ao': (1.74, 0.6, 1.25, 0.43, 0.65),
    'ou': (2.49, 0.41, 0.74, 0.08, 0.11),
    'ui iu': (1.64, 0.62, 0.97, 0.2, 0.13),
    'an en in un': (0.71, 0.24, 0.34, 0.01, 0.03),
    'ang': (2.14, 2.14, 1.93, 0.23, 0.29),
    'eng': (3.52, 2.01, 2.51, 0.93, 0.88),
    'ing': (0.47, 0.68, 0.36, 0.05, 0.45),
    'ong': (2.39, 0.95, 1.94, 0.82, 1.17),
    'ia ua': (0.76, 0.59, 0.63, -0.03, 0.03),
    'ian uan': (-0.03, 0.91, 1.3, 0.16, 0.25),
    'iang': (0, 5.29, 3.46, 2.02, 0.75),
    'iao': (0, 2.96, 0.82, 0.49, 0),
    'uang': (1.51, 0, 2.27, 1.82, 0.92),
    'uai': (0.19, -0.1, 0.62, 0.05, 0),
    'uo': (1.42, 0.23, 0.8, 0.52, 0.74),
    'ie ue': (0.72, 0.69, 0.21, -0.07, -0.03),
    'ung ng eh uen': (0, 0.21, 0.22, -0.06, 0.12),
}
FINALS = {f: strengths for words, strengths in FINAL_FAMILIES.items()
          for f in words.split()}
SYLLABLES = {i + f: (i, strengths) for i in INITIAL_CLASS
             for f, strengths in FINALS.items()}
ISOLATED_INITIAL = (1.06, 0.29, 0.34, 0.18)
CAPITAL_INITIAL = (0.85, 0.66, 0.67, 0.17)
TONE_MARKS = str.maketrans(
    "āáǎàēéěèīíǐìōóǒòūúǔùǖǘǚǜ", "aaaaeeeeiiiioooouuuuuuuu"
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    previous = carry[1] if same_doc else ""
    value = spelling_response(prefix.token_strings[-1], previous)
    strong = value > 1.0
    if same_doc and carry[2] and value > 0.3:
        value += 0.83
    return (doc, prefix.token_strings[-1], strong), float(value)


def spelling_response(s, previous):
    t = s.strip()
    if not t:
        return 0.0
    q = t.lower()
    match = re.search(r"[A-Za-z]+$", previous)
    p = match.group() if match else ""
    spaced = s[0].isspace()
    if q in REGION_WORDS:
        return 1.15
    if q in CHINESE_PLACES:
        return 2.01
    if q == "pinyin":
        return 1.70
    if not spaced and any(
        (p[-n:] + q).lower() in CHINESE_PLACES
        for n in (1, 2, 3, 4) if len(p) >= n
    ):
        return 2.20
    if q in ("uchi", "oshi"):
        return 0.34
    if q in ("kim", "lee"):
        return 0.50
    if t == "ō":
        return 1.02
    q = q.translate(TONE_MARKS)
    if not q.isascii() or not q.isalpha():
        return 0.0

    # Prefer a syllable completed across a token boundary.
    if not spaced:
        for n in (4, 3, 2, 1):
            if len(p) < n or p[-n:].lower() + q not in SYLLABLES:
                continue
            initial, strengths = SYLLABLES[p[-n:].lower() + q]
            final = (p[-n:].lower() + q)[len(initial):]
            # Mandarin's palatal and velar initials have different finals.
            if final == "uang" and initial not in ("g", "k", "h", "zh", "ch", "sh"):
                continue
            if final == "iang" and initial in ("b", "p", "m", "f", "g", "k", "h", "w"):
                continue
            group = INITIAL_CLASS[initial]
            value = strengths[group]
            if len(p) <= n:
                value += ISOLATED_INITIAL[group]
                if p[-n].isupper():
                    value += CAPITAL_INITIAL[group]
            if t.isupper() and len(t) > 1:
                value *= 0.25
            return max(0.0, value)

    if q == "he":  # Usually the English pronoun, not a surname.
        return 0.0
    if q in NAMES:
        if t.isupper():
            gain = 0.09
        elif t[0].isupper():
            gain = 0.96 if spaced else 0.61
        elif q.startswith("zh"):
            gain = 0.16 if spaced else 0.99
        elif q in COMMON_FRAGMENTS:
            gain = 0.15 if spaced else 0.06
        else:
            gain = 0.16 if spaced else 0.40
        return gain * NAMES[q]
    if q in OTHER_NAME_FORMS:
        return 0.42
    if q in FINALS and not spaced:
        return max(0.0, FINALS[q][4])
    if q in ("zh", "sh", "ch"):
        value = {"zh": 0.72, "sh": 0.14, "ch": 0.0}[q]
        if t[0].isupper() and spaced:
            value += {"zh": 0.99, "sh": 0.22, "ch": 0.1}[q]
        return value
    return 0.0

"""Creative accomplishment, reputation, and an author's body of work.

The largest negative responses distinguish authored 'work/works' from the
verb: ownership, artistic context and praise are cues. Attribution continues
into 'of' in 'works of'. Related words about achievement have smaller negative
responses. The multilingual word classes are deliberately small; most weak,
unrelated lexical responses are not modeled.
"""
READS = ()

ARTS = set('''art artist artists artistic literary literature poetry poet poets
writer writers writing author authors composer composers music musical painter
painting paintings sculpture novel novels scholarly scholar intellectual'''.split())
CHINESE_ARTS = ('文学', '艺术', '诗', '作家', '创作', '作品')
PRAISE = set('''seminal pioneering influential prolific celebrated outstanding
remarkable notable great greatest major distinguished brilliant significant'''.split())
OWNERS = set("his her their my your our whose 's ’s".split())
DETERMINERS = set('the a an this that these those other many several'.split())
VERB_CUES = set('to can could should would will may might must do does not'.split())
FOUNDATIONAL = set('pioneer pioneering seminal influential genius legacy'.split())
REPUTATION = set('famous literary masters mastery acclaimed celebrated writings'.split())
ATTRIBUTION = set('contribution contributions influence impact biography lifetime'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, arts_age, previous_letter = '', 100, False
    else:
        _, previous, arts_age, previous_letter = carry
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    if previous_letter and raw[:1].isascii() and raw[:1].isalnum():
        word = ''  # A continuation inside a word is not a separate cue.
    arts_age += 1
    creative = arts_age <= 24
    value = 0.0

    if word in ('work', 'works'):
        value = -0.04
        if previous in OWNERS:
            value -= 0.16 + (0.11 if word == 'works' else 0.0)
            if previous in ('his', 'her', 'whose'):
                value -= 0.20
        elif previous in PRAISE:
            value -= 0.36
            if previous in ('seminal', 'influential', 'pioneering'):
                value -= 0.23
        elif previous in DETERMINERS:
            value -= 0.07
        elif previous in VERB_CUES:
            value += 0.04
        elif previous == 'public':
            value += 0.13
        elif previous in ('previous', 'earlier', 'prior'):
            value -= 0.10
        if creative:
            value -= 0.14 if previous in VERB_CUES else 0.24
        if previous in ARTS:
            value -= 0.11
        if previous in ('literary', 'scholarly'):
            value -= 0.35
    elif word == 'of':
        if previous in ('work', 'works'):
            value = -0.50 if previous == 'works' else -0.27
            value -= 0.05 if creative else 0.0
        elif previous in FOUNDATIONAL:
            value = -0.35
        elif previous in REPUTATION or previous in ATTRIBUTION:
            value = -0.16
    elif word in ('figure', 'figures') and previous == 'literary':
        value = -0.60
    elif word == 'prolific':
        value = -0.52
    elif word in FOUNDATIONAL:
        value = -0.25 - (0.12 if creative else 0.0)
    elif word in REPUTATION:
        value = -0.13
    elif word in ('achievement', 'achievements'):
        value = -0.20 - (0.16 if creative else 0.0)
    elif word in ('contribution', 'contributions'):
        value = -0.04 if word == 'contribution' else -0.09
        value -= 0.17 if creative else 0.0
    elif word == 'career':
        value = -0.19 - (0.10 if previous in OWNERS else 0.0)
        value -= 0.08 if creative else 0.0
    elif word in ('impact', 'influence', 'lifetime'):
        value = -0.10 - (0.13 if creative else 0.0)
    elif word == 'his':
        value = -0.035 - (0.04 if creative else 0.0)
    elif word == 'own':
        value = -0.055
    elif word in ('成就', '贡献', '奠基', '享誉'):
        value = -0.70 if creative else -0.35
    elif word in ('作品', '的作品'):
        value = -0.25 if creative else -0.11
    elif word == '影响':
        value = -0.45 if creative else -0.13
    elif word == '巨' and creative:
        value = -0.60

    if word in ARTS or any(cue in raw for cue in CHINESE_ARTS):
        arts_age = 0
    last_letter = raw[-1:].isascii() and raw[-1:].isalnum()
    return (doc, word, arts_age, last_letter), float(value)

programs.haiku:
"""Standing and achievement words: 'career', 'work(s)', 'impact', 'famous', 'pioneering'...

The component is switched negative on nouns and adjectives about a person's standing and
accomplishments, most strongly when they follow a possessive ('his work', 'her career',
'whose works') and on 'of' right after such a word ('works of', 'pioneer of')."""

STANDING = {
    " work", " works", " career", " careers", " achievement", " achievements", " legacy",
    " contribution", " contributions", " impact", " influence", " accomplishment",
    " accomplishments", " famous", " iconic", " pioneer", " pioneering", " influential",
    " celebrated", " winner", " masters", " Prize", " prize", " biography", " critic",
    " critics", " reputation", " lifetime", " seminal", " prolific", " notable", " classic",
}
POSSESSIVE = {" his", " her", " their", " whose", "'s", "’s", " my", " your", " its"}

READS = ()


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if cur in STANDING:
        return carry, (-0.3 if prev in POSSESSIVE else -0.12)
    if cur == " of" and prev in STANDING:
        return carry, -0.2
    return carry, 0.0

programs.luna:
"""Flag creative work and achievement words in literary or biographical context."""

READS = ()

WORK_WORDS = {"work", "works"}
CREATIVE_CUES = {
    "literary", "poet", "poetry", "poetic", "poem", "poems",
    "scholar", "scholarly", "art", "artistic", "artist", "artists",
    "composer", "composers", "novel", "fiction", "theater", "theatre",
    "comic", "comics", "writer", "writers", "author", "authors",
    "writing", "creative", "intellectual", "seminal", "pioneering",
    "prolific", "notable", "influential", "prominent", "career",
}
ACHIEVEMENT_WORDS = {
    "achievement", "achievements", "contribution", "contributions",
    "legacy", "influence", "impact", "成就", "贡献", "影响", "奠基", "巨",
}
CHINESE_CUES = {"文学", "文化", "艺术", "作品", "创作", "诗", "教育", "事业", "历史", "奖"}


def _word(token):
    return token.strip().lower().strip(".,;:!?\"'’”()[]{}")


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    recent = [_word(token) for token in prefix.token_strings[-12:-1]]

    relevant = any(cue in recent for cue in CREATIVE_CUES | CHINESE_CUES)
    if word in WORK_WORDS and relevant:
        return None, -0.22

    if word == "of" and recent and recent[-1] in WORK_WORDS and relevant:
        return None, -0.22

    if word in ACHIEVEMENT_WORDS:
        if word in {"legacy", "成就", "achievement", "achievements"} or relevant:
            return None, -0.22

    return None, 0.0

programs.sol:
"""A token-local early-E spelling heuristic.

E as the first vowel is usually positive, especially in short tokens,
capitals and EE spellings. Late/final E is weaker. TH/WH, BE connectives,
and ER/EW/TES spellings receive adjustments; alternative linkers stay
positive. The same idea extends to E-family vowels in other scripts.
Han characters use only a script-average baseline. Conversation markers
have fixed values. No token IDs, preceding context or word-topic features
are used: lexical exceptions and context-dependent variation remain.
"""
READS = ()

# Common connectives that do not show the strong early-E pattern.
BE_CONNECTIVES = {"before", "below", "between", "beyond", "because"}
ALTERNATIVE_LINKERS = {"either", "neither", "whether"}


def token_value(s):
    if s.startswith('<') and s.endswith('>'):
        return {
            '<|im_start|>': 1.16, '<|im_end|>': -0.18,
            '<tool_response>': 1.58, '</tool_response>': 0.92,
            '</tool_call>': 0.70,
        }.get(s, 0.02)
    t = s.strip()
    word = ''.join(c for c in t.lower() if c.isalpha())
    # First-vowel tests in Cyrillic and Greek.
    for alphabet, e_letters in (("аеиоуыэюяё", "еэё"),
                                ("αεηιουωάέήίόύώ", "εέηή")):
        vowels = [c for c in word if c in alphabet]
        if vowels:
            if vowels[0] in e_letters:
                if vowels[0] in "ηή":
                    return 0.75
                if vowels[0] in "εέ":
                    return 1.45 if len(word) <= 3 else 0.70
                return 1.05 if len(word) <= 3 else 0.70
            return 0.15 if any(c in e_letters for c in vowels) else 0.03
    # The E row of hiragana and katakana, including voiced variants.
    kana_e = "えぇけせてねへめれげぜでべぺエェケセテネヘメレゲゼデベペ"
    if any(c in kana_e for c in word):
        return 1.20 if word[:1] in kana_e and len(word) <= 2 else 0.55
    # Hangul's 21 vowel nuclei are encoded in a regular Unicode grid.
    nuclei = [(ord(c) - 0xAC00) // 28 % 21 for c in word
              if 0xAC00 <= ord(c) <= 0xD7A3]
    if nuclei:
        if nuclei[0] in (5, 7):  # e, ye
            return 0.95
        if nuclei[0] in (1, 3):  # ae, yae
            return 0.60
        if nuclei[0] in (4, 6):  # eo, yeo
            return 0.45
        return 0.10
    if any('\u4e00' <= c <= '\u9fff' for c in word):
        return 0.26
    if word in BE_CONNECTIVES:
        return 0.03
    if word in ALTERNATIVE_LINKERS:
        return 0.95
    if word == 'e':
        return 1.78 if t.isupper() else 1.30
    if 'e' not in word:
        return 0.03
    first = word.index('e')
    early = not any(c in 'aiouy' for c in word[:first])
    if not early:
        if 'ee' in word:
            return 0.80
        if word.count('e') > 1:
            return 0.33
        if word.endswith('e'):
            return 0.03
        if word.endswith(('ed', 'es', 'er', 'ers', 'est', 'ment', 'ence')):
            return 0.06
        return 0.25
    if word.startswith(('th', 'wh')):
        return 0.0
    capital = t[:1].isupper()
    if len(word) > 5:
        if word[first-1:first] == 'r':
            return 0.43
        return 0.90 if capital else 0.66
    if first == 0:
        return 1.41 if capital else 1.02
    if word[first+1:first+2] == 's':
        return -0.09 if word[first-1:first] == 't' else 0.77
    if capital:
        return 1.06
    if 'ee' in word:
        return 1.13
    if 'ew' in word:
        return 0.20
    if word[first+1:first+2] == 'r':
        return 0.50
    if word.count('e') == 1 and word.endswith('e'):
        return 0.22 if word[first-1:first] == 'd' else 0.72
    return 0.90


def step(carry, prefix, upstream):
    return None, float(token_value(prefix.token_strings[-1]))

"""Local first-person grammar, plus i-like subword continuations.

Predict a positive response to 'I am/have/need/want', especially I'm/I've,
and a negative response to 'I think/mean/say/guess' and mental-state verbs.
Other personal subjects have much weaker responses. A second, orthographic
rule handles fragments following i/j/y and related Greek/Cyrillic endings:
o/u-initial Latin fragments tend positive, a/i-initial ones negative.
The first-person signal weakens across intervening auxiliaries, adverbs
and negation particles. Bare 'I' is stronger than space-prefixed ' I',
especially in positive constructions at document start. These are partial
approximations: unrecognized cases return zero. Documents reset all state.
"""
import unicodedata

READS = ()

ASSERTION = {'think', 'mean', 'say'}
CONJECTURE = {'guess', 'suppose'}
MENTAL_OR_SPEECH = {
    'know', 'thought', 'said', 'believe', 'find', 'feel', 'suspect',
    'suggest', 'tell', 'assure', 'assume', 'imagine', 'notice',
}
PAST_OR_AGREEMENT = {'found', 'knew', 'told', 'agree'}
POSITIVE = {
    "'m": 1.40, '’m': 1.29, "'ve": 1.16, '’ve': 1.15,
    'have': 0.94, 'am': 0.40, 'need': 0.81, 'want': 0.55,
    'like': 0.31, 'love': 0.26, 'don': 0.27,
    "'d": 0.27, '’d': 0.27, "'ll": 0.18, '’ll': 0.18,
    'was': 0.12, 'would': 0.11,
}


def first_person(token):
    word = token.strip().lower()
    if word in POSITIVE:
        return POSITIVE[word]
    if not token.startswith(' '):
        return 0.0
    if word in ASSERTION:
        return -1.93
    if word in CONJECTURE:
        return -1.67
    if word == 'see':
        return -1.14
    if word in MENTAL_OR_SPEECH:
        return -0.83
    if word in PAST_OR_AGREEMENT:
        return -0.45
    if word in {'should', 'must', 'cannot'}:
        return -0.32
    return -0.20 if word == 'can' else 0.0


def fragment(previous, token):
    if not previous or not token or token[0].isspace():
        return 0.0
    last = unicodedata.normalize('NFKC', previous[-1]).lower()
    first = unicodedata.normalize('NFKD', token[0].lower())[0]
    if last.lower() in 'ijy':
        value = {'o': 0.54, 'ø': 0.54, 'u': 0.24,
                 'a': -0.30, 'i': -0.32}.get(first, 0.0)
        return value * (0.60 if last.lower() == 'y' else 1.0)
    if last in 'ιί':
        if first == 'ο':
            return 1.30
        if first in 'αεηυω':
            return 0.72
        if first == 'ν':
            return 0.62
    if last in 'иії':
        if first == 'д':
            return -0.56 if last == 'і' else -0.30
        if token.startswith('ров'):
            return 1.15
        if first == 'о':
            return 0.70
        if first in 'иії':
            return -0.65
        if first in 'ая':
            return -0.17
    return 0.0


# A short first-person verb phrase may contain a modal, adverb or negation.
PHRASE_MODIFIERS = {
    'would', 'will', 'might', "'d", '’d', "'ll", '’ll',
    'really', 'just', 'still', 'also', 'only', 'always', 'often',
    'never', 'personally', 'currently', 'already', 'certainly',
    'do', 'did', 'don', 'dont', 'not', "'t", '’t', 'to',
}
WEAK_MODALS = {'can', 'could', 'should', 'must', 'cannot', 'may'}
OTHER_SUBJECTS = {'you', 'we', 'they', 'he', 'she'}
MENTAL_WORDS = ASSERTION | CONJECTURE | MENTAL_OR_SPEECH | {'see'}


def is_first_person(token):
    return (token[-1:] in {'I', 'i'} and
            (len(token) == 1 or
             not (token[-2].isalnum() or token[-2] == '_')))


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    reset = carry is None or carry[0] != doc
    previous = '' if reset else carry[1]
    strength = 0.0 if reset else carry[2]
    previous_was_first = False if reset else carry[3]
    word = token.strip().lower()
    value = fragment(previous, token)
    verb = first_person(token)
    if strength and verb:
        value = strength * verb
        if is_first_person(previous):
            if previous[-1] == 'i':
                value *= 0.83
            elif previous == 'I':
                if previous_was_first and value > 0:
                    value *= 1.75
                else:
                    value *= 1.25 if value > 0 else 1.08
    else:
        subject = previous.strip().lstrip('"“(‘’\'').lower()
        contraction = word.replace('’', "'")
        if subject in OTHER_SUBJECTS:
            if word in MENTAL_WORDS:
                value = verb * 0.20
            elif contraction in {'have', 'has', "'ve", 'need', 'needs'}:
                value = 0.12
            elif contraction in {'are', "'re"}:
                value = 0.17 if subject == 'we' else 0.10
    if is_first_person(token):
        next_strength = 1.0
    elif word in PHRASE_MODIFIERS:
        next_strength = strength * 0.60
    elif word in WEAK_MODALS:
        next_strength = strength * 0.35
    else:
        next_strength = 0.0
    return (doc, token, next_strength, reset), float(value)

