"""A small first-person stance heuristic for this residual component.

It predicts a negative response when a first-person subject is followed by a
mental or perceptual verb, and a positive response for common first-person
auxiliary forms. Other contexts are left at zero.
"""
READS = ()

STANCE_VERBS = {
    "think", "thought", "know", "knew", "guess", "see", "saw",
    "feel", "felt", "say", "said",
}
POSITIVE_FORMS = {"have", "'ve", "’ve", "am", "'m", "’m"}


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0

    previous = prefix.token_strings[-2].strip().lower()
    current = prefix.token_strings[-1].strip().lower()
    current = current.strip(".,!?;:()[]{}\"“”")

    if previous in {"i", "i'", "i’"}:
        if current in STANCE_VERBS:
            return None, -0.9
        if current in POSITIVE_FORMS:
            return None, 0.8
    return None, 0.0

