    if not s:
        return .001
    if all('一' <= c <= '鿿' for c in s):
        return .066 if len(s) == 1 else -.031
    if all('ぁ' <= c <= 'ゟ' for c in s):
        return .15 if len(s) == 1 else -.018
    return .003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
