        value = .30 if token.startswith(' ') else .20
        if before == 'one':
            value = 1.18
        elif before == 'whether':
            value = 1.36
        elif before in {'than', 'more', 'his', 'him', 'he', 'some', 'all'}:
            value = .90
        elif before in NUMBERS:
