"""Activation of layers.0.mlp.down_proj:1653, predicted from the current token (plus a few context rules).

The component is diffuse: most of its variance is spread over many ordinary tokens, and no
single concept covers it. What it does pick out, roughly in order of strength:
  * the word 'user' opening a new document (the chat role tag, 2nd token of a document): very large;
  * 'or', and 'and' after a number word ('one or', 'two or', 'hundred and'): positive;
  * Japanese and Korean grammatical particles (の に を が は も と か な り; 의 에 를 을 로 이 가):
    positive, as are the underscore and ampersand;
  * Chinese, Japanese, Korean and Thai script characters, and the hyphen: weakly positive;
  * the possessive 's: moderately positive;
  * a few function words in other languages and English prepositions: weakly positive or negative.
Everything else is predicted as 0 (its typical value).
"""
import unicodedata

READS = ()

PARTICLES = set("のにをがはもとかなり") | set("의에를을로이가")
OR_WORDS = {"or", " or", " OR", "/or"}
NUMBER_WORDS = {"one", "two", "three", "four", "five", "ten", "hundred", "thousand", "twenty", "dozen"}
POSSESSIVE = {"'s", "’s"}
WEAK_POSITIVE = {"_", "&", "-", " de", " que", " on", " by", " over", " while", " else"}
WEAK_NEGATIVE = {" la", " per", " sure", " just", "、"}
SCRIPTS = ("CJK", "HIRAGANA", "KATAKANA", "HANGUL", "THAI")


def is_script_char(s):
    """A single character from a Chinese, Japanese, Korean or Thai script."""
    return len(s) == 1 and any(k in unicodedata.name(s, "") for k in SCRIPTS)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    docs = prefix.document_ids
    # Position within the current document (positions restart at each document).
    start = len(docs) - 1
    while start > 0 and docs[start - 1] == docs[-1]:
        start -= 1
    pos = len(docs) - 1 - start
    prev = prefix.token_strings[-2].strip().lower() if len(docs) > 1 else ""
    if tok == "user" and pos == 1:
        return None, 1.9
    if tok in OR_WORDS:
        return None, 0.27
    if tok.strip() == "and" and prev in NUMBER_WORDS:
        return None, 0.65
    if tok in PARTICLES:
        return None, 0.35
    if tok in POSSESSIVE:
        return None, 0.17
    if tok in WEAK_POSITIVE or is_script_char(tok):
        return None, 0.07
    if tok in WEAK_NEGATIVE:
        return None, -0.08
    return None, 0.0

programs.sol:
"""Cooperative-work vocabulary, especially the word 'with' after it.

Each lexical family has a small response on its own and a larger negative
response when followed by 'with'. Work/closely/together phrases strengthen
this signal. Chinese cooperation vocabulary is included too. The short
text tail joins split words and resets at document boundaries. Other
vocabulary and finer context-dependent variation are left unmodeled.
"""
import re

READS = ()
WORK = {'work', 'works', 'worked', 'working'}
# Word stem, response on that word, response on a following 'with'.
FAMILIES = (
    ('collabor', -0.65, -1.85),
    ('partner', -0.30, -1.55),
    ('consult', -0.15, -1.45),
    ('cooperat', -0.13, -1.15),
    ('coordinat', 0.0, -1.05),
    ('assist', 0.0, -1.05),
    ('involv', 0.0, -1.05),
    ('engag', -0.1, -0.85),
    ('interact', 0.0, -0.65),
    ('interfer', 0.0, -0.65),
    ('integrat', 0.0, -0.7),
    ('communicat', 0.0, -0.52),
    ('combin', 0.0, -0.52),
)
COOPERATION_ZH = set('''合作 协作 協作 协同 協同 协调 協調 联合 聯合
联手 聯手 携手 攜手 牵手 牽手 协助 協助 帮扶 幫扶'''.split())
# Chinese words for closeness, coordination, assistance, or joining forces.
CLOSENESS_ZH = {'紧密', '緊密', '密切', '配合', '合力'}
ADVERBS = {'directly', 'actively', 'extensively', 'seamlessly'}


def response(word):
    if word in WORK:
        return 0.0, -1.85 if word in {'worked', 'working'} else -1.4
    if word in {'help', 'helps', 'helped', 'helping'}:
        return 0.0, -0.7
    if word in {'together', 'conjunction', 'tandem'}:
        return 0.0, -0.75
    if word.startswith(('deal', 'connect', 'align', 'correlat')):
        return 0.0, -0.3
    for stem, direct, connector in FAMILIES:
        if word.startswith(stem):
            return direct, connector
    return 0.0, 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    words = re.findall(r'[a-z]+', tail.lower())
    prev = words[-1] if words else ''
    earlier = words[-2] if len(words) > 1 else ''
    text = (tail + token)[-80:]
    ending = re.search(r'[a-z]+$', text.lower())
    word = ending.group() if ending else ''
    value = response(word)[0]
    if token.strip().lower() == 'with':
        value = response(prev)[1]
        if prev == 'closely':
            value = 1.2 * response(earlier)[1] - 0.65
        elif prev == 'well':
            value = 0.35 * response(earlier)[1]
        elif prev in {'properly', 'correctly'}:
            value = -1.05
        elif prev in ADVERBS:
            value = response(earlier)[1]
        elif prev == 'jointly':
            value = -0.7
        elif prev in {'team', 'teamed', 'teaming'}:
            value = -1.5
        elif prev == 'up' and earlier.startswith('team'):
            value = -1.4
    elif word == 'closely':
        value = -2.4 if prev in WORK else -0.75
    elif word in {'together', 'alongside'}:
        value = -1.15 if prev in WORK else 0.0
        if prev not in WORK and word == 'alongside':
            value = -0.35
    elif token in COOPERATION_ZH:
        value = -0.8
    elif token in CLOSENESS_ZH:
        value = -0.55
    elif token in {'与', '與'}:
        value = -0.15
    elif token in {'会同', '會同'}:
        value = -2.0
    return (doc, text), value

"""Lexical small-number/ordinal detector, not a calculator.

The largest responses are to single CJK numerals. Written-out counts,
ordinals, Roman numerals, counting roots and weekday names also respond.
Ordinary ASCII digit tokens do not. Compounds and fragments are weaker.
The rules approximate the strong number-related responses, not the weak
background activations on ordinary words. Coefficients were fit on training
text; no numerical arithmetic is inferred from this feature.
"""
READS = ()

CARDINALS = (
    'zero one two three four five six seven eight nine ten eleven twelve '
    'thirteen fourteen fifteen sixteen seventeen eighteen nineteen'
).split()
ORDINALS = (
    'zeroth first second third fourth fifth sixth seventh eighth ninth tenth'
).split()
SMALL = {
    0: 0.57,
    1: -0.10,
    2: 0.90,
    3: 1.06,
    4: 1.38,
    5: 1.35,
    6: 1.60,
    7: 1.46,
    8: 1.49,
    9: 1.45,
}
HAN = {
    '零': 0.78,
    '一': 1.58,
    '二': 3.49,
    '三': 3.34,
    '四': 4.30,
    '五': 4.79,
    '六': 5.46,
    '七': 4.70,
    '八': 5.99,
    '九': 4.52,
    '十': 2.42,
    '两': 1.31,
    '兩': 1.16,
}
ROMAN = {
    'ii': 1.03,
    'iii': 1.31,
    'iv': 1.32,
    'vi': 1.37,
    'vii': 1.73,
    'viii': 2.00,
    'ix': 0.98,
    'xi': 0.61,
    'xii': 1.16,
    'xiii': 1.17,
    'xiv': 1.43,
    'xv': 0.58,
    'xvi': 1.19,
}
# Number names and roots in several European languages.
FOREIGN_TWO_THREE = set((
    'deux trois zwei zwe drei tres três dois duas '
    'два две дв двух три треть втор'
).split())
FOREIGN_FOUR_FIVE = set((
    'quatre cuatro vier fünf fün cinco четы четыре пят'
).split())
ROOTS = {
    'tri': 0.59,
    'quad': 0.41,
    'quadr': 0.71,
    'pent': 0.84,
    'quint': 0.64,
    'hex': 1.15,
    'sept': 0.94,
    'oct': 1.12,
    'sext': 1.16,
    'tw': 0.52,
}
WEEKDAYS = set((
    'monday tuesday wednesday thursday friday saturday '
    'uesday nesday riday aturday'
).split())
NUMBER_ENDINGS = set((
    'teen teenth eenth elfth ifth venth irteen entieth'
).split())
TENS = set('twenty thirty forty fifty sixty seventy eighty ninety'.split())


def lexical_value(token):
    word = token.strip(' \n\t-_.([')
    lower = word.lower()
    spaced = token.startswith(' ')
    if lower in CARDINALS or lower in ORDINALS:
        ordinal = lower in ORDINALS
        n = (ORDINALS if ordinal else CARDINALS).index(lower)
        value = SMALL.get(n, 0.66 if n == 10 else 1.35)
        if ordinal:
            if n < 4:
                value *= 0.75
            if n == 10:
                value = 0.93
        if value > 0 and word.istitle():
            value *= 1.20 if n < 10 else 1.0
        if value > 0 and not spaced and word.islower():
            value -= 0.08
        if token.startswith('-') and value > 0:
            value *= 0.65
        if lower == 'ten' and not spaced and word.islower():
            value = 0.10
        return value
    if lower in TENS:
        return 0.65
    if lower in ('hundred', 'thousand'):
        return -0.27
    if lower in ('twice', 'triple', 'secondary', 'tertiary'):
        return 0.60
    if lower in ROMAN:
        value = ROMAN[lower]
        if word.istitle():
            return 0.39
        if word.islower():
            if lower == 'iii':
                return 0.88 if spaced else 1.11
            if lower == 'ii':
                return 0.70 if spaced else 0.58
            return value * (0.42 if spaced else 0.22)
        return value - (0.45 if not spaced and lower in ('iv', 'vi', 'ix') else 0)
    if lower in ROOTS:
        value = ROOTS[lower]
        if lower in ('oct', 'sept') and word.istitle():
            value *= 0.50
        return value
    if lower in FOREIGN_TWO_THREE:
        return 0.80
    if lower in FOREIGN_FOUR_FIVE:
        return 1.15
    if lower in NUMBER_ENDINGS:
        return 1.15
    if lower in WEEKDAYS:
        return 0.85 if spaced else 1.10
    if lower == 'sunday':
        return 0.40
    if word in HAN:
        return HAN[word]
    numerals = [ch for ch in word if ch in HAN]
    if numerals:
        strength = sum(HAN[ch] for ch in numerals) / len(numerals)
        if len(numerals) == len(word):
            if word.startswith('十'):
                return 2.30
            if word.endswith('十'):
                return 1.70
            return 0.50 * strength
        if word.startswith('第'):
            return (0.44 if len(word) == 2 else 0.27) * strength
        if len(word) == 2:
            if word in ('一个', '一個', '一般', '一些', '一样', '一樣'):
                return 0.08
            return (0.45 if word[-1] in '年人大小' else 0.32) * strength
        return 0.16 * strength
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    start = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if start else prefix.token_strings[-2]
    value = lexical_value(token)
    if token in ('st', 'nd', 'rd', 'th'):
        value = 0.30 if previous.isdecimal() else 0.0
    if token == '�' and not start:
        # Recover a numeral finished by a split UTF-8 byte.
        char = prefix.text_prefixes[-1][-1:]
        if char in HAN:
            value = min(8.0, 1.5 * HAN[char])
        elif char.isnumeric() and not char.isascii():
            value = 0.60
    if token in HAN and previous in HAN:
        value *= 0.80
    return None, float(value * (0.80 if start else 1.0))

