"""Number-word detector for layers.0.mlp.down_proj component 1655.

The component's activation is almost entirely a function of the current token:
it fires on number words that name a count or position (two..nine, the Chinese
numerals 二..九, Roman numerals II..VIII, the ordinals second..ninth, 第二..第五),
and stays silent on "one", "first", "zero", the Arabic digits and most other text.
Its strength depends on the word: Chinese 2-9 are the strongest (about 4), then
English four..nine and Roman III, then two/three and the ordinals; "one" and
"first" are near zero.

The program is stateless: it looks only at the newest token and returns the
strength for that word, or 0 for everything else.
"""

READS = ()

# Strength for each kind of number token (activation units, roughly the component's value).
CHINESE_DIGITS_2_TO_9 = 4.0   # 二 三 四 五 六 七 八 九
CHINESE_TEN = 2.5             # 十
CHINESE_ONE = 1.6             # 一
CHINESE_TWO_LIANG = 1.1       # 两 兩 (also "two")
ENGLISH_2_TO_9 = 1.3          # two .. nine (any case)
ENGLISH_11_TO_19 = 1.2        # eleven .. nineteen
ENGLISH_TENS_AND_TEN = 0.5    # ten, twenty, thirty
ENGLISH_ZERO = 0.6            # zero
ENGLISH_ORDINAL_LATE = 1.2    # third .. ninth
ENGLISH_SECOND = 0.7          # second
ROMAN_UPPER = 1.2             # II III IV VI VII VIII
ROMAN_LOWER = 0.6             # ii iii iv vi vii viii
ORDINAL_CHINESE = 1.8         # 第二 .. 第九 (第一 is 0.7)
WEEKDAY = 0.9                 # Monday .. Saturday
OTHER_WORD_COUNT = 1.0        # a word that starts with 两/二/三..十, e.g. 两个, 三种
FOREIGN_2_TO_9 = 0.8          # deux, trois, zwei, два, tri, ...
FOREIGN_SET = {"deux", "trois", "quatre", "cinq", "sept", "zwei", "drei", "fünf",
               "два", "три", "четыре", "пять", "tri", "tres", "cuatro"}

ENGLISH_2_TO_9_SET = {"two", "three", "four", "five", "six", "seven", "eight", "nine"}
ENGLISH_11_TO_19_SET = {"eleven", "twelve", "thirteen", "fourteen", "fifteen",
                        "sixteen", "seventeen", "eighteen", "nineteen"}
ENGLISH_TENS_SET = {"ten", "twenty", "thirty"}
ENGLISH_ORDINAL_SET = {"third", "fourth", "fifth", "sixth", "seventh", "eighth", "ninth"}
ROMAN_UPPER_SET = {"II", "III", "IV", "VI", "VII", "VIII"}
ROMAN_LOWER_SET = {"ii", "iii", "iv", "vi", "vii", "viii"}
WEEKDAY_SET = {"Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"}
CHINESE_DIGIT_SET = set("二三四五六七八九")


def strength(word: str) -> float:
    """How strongly a single token (already stripped of its leading space) fires."""
    lower = word.lower()
    if word in CHINESE_DIGIT_SET:
        return CHINESE_DIGITS_2_TO_9
    if word == "十":
        return CHINESE_TEN
    if word == "一":
        return CHINESE_ONE
    if word in ("两", "兩"):
        return CHINESE_TWO_LIANG
    if len(word) == 2 and word[0] == "第" and word[1] in CHINESE_DIGIT_SET:
        return ORDINAL_CHINESE
    if word == "第一":
        return 0.7
    if lower in ENGLISH_2_TO_9_SET:
        return ENGLISH_2_TO_9
    if lower in ENGLISH_11_TO_19_SET:
        return ENGLISH_11_TO_19
    if lower in ENGLISH_TENS_SET:
        return ENGLISH_TENS_AND_TEN
    if lower == "zero":
        return ENGLISH_ZERO
    if lower in ENGLISH_ORDINAL_SET:
        return ENGLISH_ORDINAL_LATE
    if lower == "second":
        return ENGLISH_SECOND
    if word in ROMAN_UPPER_SET:
        return ROMAN_UPPER
    if word in ROMAN_LOWER_SET:
        return ROMAN_LOWER
    if word in WEEKDAY_SET:
        return WEEKDAY
    if lower in FOREIGN_SET:
        return FOREIGN_2_TO_9
    if len(word) > 1 and word[0] in CHINESE_DIGIT_SET | {"十", "两", "兩"}:
        return OTHER_WORD_COUNT
    return 0.0


def step(carry, prefix, upstream):
    """Activation at the newest token: its number-word strength, else 0."""
    return carry, strength(prefix.token_strings[-1].strip())

programs.sol:
"""Mostly a negative response to separately encoded sentence punctuation.

Periods attached to newlines or letters are quiet. A bare period is strongest
near the beginning of a document, after longer tokens, and away from other dots.
Decimal notation and numbered-list markers weaken it. Question marks, CJK
full stops, exclamation marks and punctuation-plus-period tokens have smaller
or separate responses. These are text-shape rules, not a full sentence parser.
"""
import re

READS = ()


def bare_period(previous, recent, text, position):
    if not previous or previous == '.':
        return 0.04
    early = 1.0 / (1.0 + position / 64.0)
    dots = min(3, sum(token.count('.') for token in recent))
    word = previous.strip()
    if word.isdigit():
        match = re.search(r'\d+$', text.rstrip())
        number = match.group() if match else word
        before = text.rstrip()[:-len(number)]
        if not before.split('\n')[-1].strip():
            return 0.0  # A number alone on its line: a likely list label.
        value = -0.68 - 0.41 * early - 0.072 * min(len(number), 6)
        value += 0.225 * dots
        if before.endswith('.'):
            value += 0.335
    else:
        value = -1.15 - 0.77 * early + 0.192 * dots
        value += 0.21 * max(0, 4 - len(word)) / 3
        if word.isupper():
            value -= 0.08
        if not word.isascii():
            value += 0.19
        if len(recent) > 1 and '\n' in recent[-2]:
            value += 0.62
        if position == 1:
            value += 0.65
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, recent, text = 0, (), ''
    else:
        _, position, recent, text = carry
    token = prefix.token_strings[-1]
    previous = recent[-1] if recent else ''
    value = -0.002
    if '\n' not in token and '\r' not in token:
        if token == '.':
            value = bare_period(previous, recent, text, position)
        elif token == ' .':
            dots = min(3, sum(t.count('.') for t in recent))
            value = -0.85 + 0.25 * dots
            if not previous.strip():
                value = -0.04
        elif token == '。':
            value = -0.35 - 0.49 / (1 + position / 64)
        elif token.strip() in ('?', '？'):
            value = -0.55 - 0.27 / (1 + position / 64)
            if token != '?':
                value = -0.34 if token.strip() == '?' else -0.17
        elif token.strip() == '!':
            value = -0.20 - 0.35 / (1 + position / 64)
        elif token in ('."', '.”', ".'", '.’'):
            value = -0.81
        elif token in ('.)', '.]'):
            value = -0.25
        elif token.endswith('.') and token.count('.') == 1:
            # Closing punctuation followed by a period, not a path or a word.
            allowed = set(" .()]}\"'»”’`$%")
            if all(c in allowed for c in token):
                value = -1.4
                if '()' in token:
                    value = -0.35
                elif '%' in token:
                    value = -1.82
                elif '"' in token or "'" in token:
                    value = -0.67 if ')' in token else -1.10
    carry = (document, position + 1, (recent + (token,))[-16:],
             (text + token)[-200:])
    return carry, float(value)

