programs.haiku:
"""Units of time and measure (time, year, month, day, hour, dollars, feet, percent, ...).

What it does: a unit noun is positive when it stands as a plain noun phrase after a
determiner ("the time", "this year", "the following years", "the same day"), weakly positive
after "a" or an ordinary word, and negative after a count word ("two years", "five times",
"several days", "one day" weakly). A digit right before the unit ("3 years") gives nothing.
Magnitude words (hundred, thousand, million, percent) are negative after a count or a digit.
"more" after a count ("a few more", "two more") is negative. "of" after a magnitude word
("thousands of", "percent of") is negative. Everything else is 0. This is a concept-level
approximation: it captures the sign pattern and main token classes, not the full size."""
READS = ()

TIME_WORDS = {"time", "times", "year", "years", "month", "months", "hour", "hours", "minute",
              "minutes", "seconds", "decade", "decades", "century", "centuries", "week", "weeks",
              "day", "days", "时间", "时", "年", "月", "日", "週", "周", "時", "時間"}
MEASURE_WORDS = {"dollar", "dollars", "pound", "pounds", "mile", "miles", "gram", "grams",
                 "inch", "inches", "feet", "meter", "gallon", "tablespoons", "calories",
                 "pixels", "pages", "digits", "generations"}
MAGNITUDES = {"hundred", "hundreds", "thousand", "thousands", "million", "millions", "billion",
              "percent", "千", "萬", "万"}
NUMBER_WORDS = {"two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven",
                "twelve", "fifteen", "twenty", "thirty", "forty", "fifty", "hundred", "thousand"}
VAGUE_COUNTS = {"few", "several", "many", "couple", "bit", "little"}
DETERMINERS = {"the", "this", "that", "these", "those", "my", "your", "his", "her", "its", "our",
               "their", "last", "next", "every", "each", "same", "past", "following", "recent",
               "new", "all", "present"}
WEAK = {"a", "an", "first", "some", "per", "long", "short", "second", "by", "over"}


def context(prev):
    """How the word before a unit noun pushes the unit's activation."""
    if prev.isdigit():
        return 0.0
    if prev in NUMBER_WORDS or prev in MAGNITUDES:
        return -1.0
    if prev == "one" or prev in VAGUE_COUNTS:
        return -0.35
    if prev in DETERMINERS:
        return 1.0
    if prev in WEAK:
        return 0.3
    return 0.6


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if word in TIME_WORDS or "time" in word or "year" in word:
        return carry, context(prev)
    if word in MEASURE_WORDS:
        return carry, 0.6 * context(prev)
    if word in MAGNITUDES:
        if prev.isdigit():
            return carry, -0.6
        return carry, -1.3 if prev in NUMBER_WORDS else 0.5 * context(prev)
    if word == "more" and (prev in NUMBER_WORDS or prev in VAGUE_COUNTS or prev == "a"):
        return carry, -1.4
    if word == "of" and prev in MAGNITUDES:
        return carry, -0.7
    return carry, 0.0

