)
# Familiar French word-final spelling fragments.
FRENCH_ENDINGS = frozenset(
    (
        "agne aille ailles aire aires esse ille illes ique iques itaire ière ières "
        "naire nelle nelles ogne oire tre ville vre âtre ème èmes ère ères ême ître "
    ).split()
)
SHORT_FUNCTIONS = frozenset(
    (
        "avait avec avoir avons ce ces cet cette comme entre faire fait font fut je "
        "mais me ne ont se ses son sont te était être "
    ).split()
)
OTHER_FUNCTIONS = frozenset(("ainsi aussi cela ils plus quel quelle ").split())
FAMILIAR_FRENCH = frozenset(
    (
        "belle bonne cause cherche courte deux femme feu fille fois fond force "
        "forte france grande grosse haute homme masse monde petite place plusieurs "
        "pose rencontre rencontres seule temps toute trois valeur vie visite "
    ).split()
)
NEUTRAL = frozenset(
    (
        "après aux bien dans depuis du elle elles en il la le les nous on où par "
        "pas peu pour quand rien sans sous sur toujours tous très un vous "
    ).split()
)
SHARED_E_WORDS = frozenset(
    (
        "are base be because before case change close code come create delete else "
        "example false file give have here image large line made make message "
        "module more name none note page phase possible range same sentence simple "
        "size some space table take the there these those time true type use value "
        "were write "
    ).split()
)

CONTENT_CUES = FAMILIAR_FRENCH - {
    "place",
    "cause",
    "force",
    "france",
    "deux",
    "trois",
    "fois",
    "temps",
    "feu",
    "plusieurs",
}


def starts_word(s, previous):
    return (
        not previous
        or previous[-1:].isspace()
        or s[:1].isspace()
        or (s[:1].isupper() and not s.isupper())
    )


def spelling_weights(s, previous):
    w = s.lower().strip()
    if not w or not all(c.isalpha() or c == "'" for c in w):
        return QUIET
    if starts_word(s, previous):
        if w in CORE_WORDS:
            return CORE_WORDS[w]
        if w in SHORT_FUNCTIONS:
            return (-0.006, 0.772)
        if w in {"est", "et"}:
            return (0.039, 0.671)
        if w in {"notre", "votre", "même"}:
            return (0.368, 0.500)
        if w in OTHER_FUNCTIONS:
            return (-0.029, -0.815)
        if w in FAMILIAR_FRENCH:
            return (0.099, 0.976)
        if w in {"ré", "é"}:
            return (0.108, -0.551)
        if w in NEUTRAL or w in OTHER:
            return QUIET
        if w not in SHARED_E_WORDS and w.endswith(("e", "es")):
            return (0.003, 0.578)
        if w.endswith(("ité", "ités")):
            return (0.003, 0.486)
        return QUIET
    if w in FRENCH_ENDINGS or (
        len(w) < 9
        and w.endswith(
            ("aire", "aires", "ique", "iques", "ière", "ières", "ienne", "iennes")
        )
    ):
        return (0.401, 1.036)
    if len(w) < 6 and w.endswith(("ée", "ées")):
        return (0.337, 0.111)
    if len(w) < 7 and w.endswith("es"):
        return (0.007, 0.990)
    if len(w) < 7 and w.endswith("e"):
        return (-0.061, 0.765) if w in {"ate", "are", "age"} else (0.012, 1.277)
    if w in {"ait", "aient", "oit", "ient", "ent", "ons", "ez", "rent", "vent"}:
        return (-0.001, 1.066)
    if w.endswith(
        ("ment", "ments", "tion", "tions", "eur", "eurs", "ité", "ités", "iers")
    ):
        return (0.003, 0.486)
    if (w in {"é", "és"}) or (
        len(w) < 4 and (w.startswith("é") or any(c in "èêâôû" for c in w))
    ):
        return (0.108, -0.551)
    if w.isascii() and w.isalpha() and len(w) < 7:
        if len(w) == 1 or (len(w) < 4 and ("ou" in w or w in {"u", "du", "us"})):
            return (0.004, -0.294)
    return QUIET


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0.0, 0.0, 0.0, 0.0, "")
    _, french, other, long_french, long_other, previous = carry
    context = 0.25 * french / (french + other + 0.8) + 0.75 * long_french / (
        long_french + long_other + 1.5
    )
    base, gain = spelling_weights(s, previous)
    value = base + gain * context
    w = s.lower().strip()
    f = e = 0.0
    if starts_word(s, previous):
        if w in FRENCH:
            f = 2.0 if w in STRONG else 1.0
        if w in OTHER:
            e = 1.5
        if w in {"de", "que", "en", "un", "la", "se", "me", "es"}:
            f = 0.25
    if any(c in s for c in "éèêçœàùâôû") or w in FRENCH_ENDINGS:
        f = max(f, 1.0)
    if starts_word(s, previous) and w in CONTENT_CUES:
        f = max(f, 1.0)
    carry = (
        doc,
        0.72 * french + f,
        0.72 * other + e,
        0.96 * long_french + f,
        0.96 * long_other + e,
        s,
    )
    return carry, float(value)

"""Approximate an op-centered lexical response, using spelling and word families.

Short op fragments, operation and opposite receive large negative activations.
Open/hope/property-like words mostly do not. Chinese counterparts of operate,
cooperate, copy, shop, hop, opinion and opportunity also receive negatives.
A short unfinished-word suffix adjusts mathop and some split-word continuations.
It resets at document boundaries. Other context-dependent variation is omitted.
"""
import re

READS = ()
# Chinese counterparts of operation/cooperation and op-containing word families.
CHINESE = {
    # Operate, cooperate, operate/do, copy.
    '操作': -3.5, '合作': -3.0, '操': -1.8, '抄': -1.8,
    # Shop, hop, opinion, opportunity.
    '购物': -0.9, '跳': -0.8, '意见': -1.1, '机会': -1.2,
    # Assignment/work, running, business management, operation.
    '作业': -0.5, '运行': -0.5, '经营': -0.8, '运营': -0.9,
}


def response(raw, previous=''):
    spaced = raw.startswith(' ')
    word = raw.strip().strip('._-/()[]{}<>:;,\"\'')
    s = word.lower()
    chinese = s.removeprefix('的')
    if chinese in CHINESE:
        return CHINESE[chinese]
    if s == 'оп':
        return -2.9 + 0.7 * spaced
    if s.startswith('опер'):
        return -3.2
    if s in ('op', 'ops'):
        if raw[:1].isalpha():
            if previous == 'math':
                return -7.3
            if s == 'ops' and previous.endswith(('lo', 'tro')):
                return -1.0
            if previous.endswith(('sc', 'aut', 'tro', 'sco', 'bi')):
                return -3.0
        if s == 'ops':
            return -4.2
        if word == 'OP':
            return -4.2
        return (-5.5 if word == 'Op' else -5.0) + 0.9 * spaced
    if s in ('operation', 'operations', 'opposite'):
        return -3.4
    if s == 'operative':
        return -1.4 if spaced else -3.1
    if s == 'oper':
        return -3.1 + 0.6 * spaced
    if s.startswith(('operat', 'cooper', 'coop')):
        return -2.3
    if s.startswith('opportun'):
        return -1.8
    if s.startswith('opposed'):
        return -0.75
    if s.startswith(('oppos', 'opinion')):
        return -1.4
    if s.startswith(('open', 'hope', 'prop', 'drop', 'trop', 'loop',
                     'lope', 'copyright')):
        return 0.0
    if s.startswith(('top', 'stop', 'rop', 'crop', 'popul', 'pope',
                     'popup', 'option', 'optim', 'optic', 'oppon')):
        return -0.4
    if s.startswith('pop'):
        return -1.7
    if s in ('chop', 'hop', 'cop', 'mop', 'dop', 'kop'):
        return -2.7
    if s == 'copies':
        return -0.6
    if s.startswith(('copy', 'copi', 'shop', 'chop', 'hop', 'workshop')):
        return -1.2
    if s.startswith('opp') or s in ('opus', 'oping'):
        return -2.5
    if s.startswith('op'):
        return -1.6 if len(s) <= 6 else -0.9
    if 'op' in s:
        return -1.8 if len(s) <= 4 else -0.15
    return 0.0


