READS = ()

DETERMINERS = {'a', 'an', 'the', 'some', 'this', 'these', 'those'}
MESSAGE_FUNCTIONS = {
    'print', 'printf', 'println', 'writeln', 'write', 'writeline',
    'log', 'info', 'debug', 'warn', 'errorf', 'perror', 'sprintf',
}
LOOKUP_FUNCTIONS = {
    'get', 'put', 'getint', 'getstring', 'getparameter', 'find', 'findall',
}


def separate_quote(previous, quote):
    word = previous.strip().lower()
    last = previous.rstrip()[-1:] or 'START'
    single = quote == "'"
    if previous and not word:
        return -0.8 if '\n' in previous else -1.4
    if last in {',', ':'}:
        if '"' in previous or "'" in previous:
            return -1.85 if single else -1.6
        return -1.3 if single else -0.8
    if last == '=':
        return -1.4 if single else -1.25
    if last in set('+-|/<>('):
        return -0.9
    if last == '.':
        return -0.47 if single else -0.32
    if word in DETERMINERS:
        return 0.2 if single else 0.28
    if word in {'case', 'return', 'yield'}:
        return -1.05
    return -0.45 if single else -0.2


def quote_strength(before, quote, spaced, previous):
    """Classify the punctuation immediately preceding the final quote."""
    single = quote == "'"
    edge = before[-1:] or 'START'
    if not before:
        if spaced:
            return separate_quote(previous, quote)
        if '\n' in previous or not previous:
            return -0.5
        return -0.1 if single else 0.0
    if edge == '\\':
        if '(' in before:
            return -1.35
        if '[' in before or '{' in before:
            return -1.7
        if '=' in before or ':' in before:
            return -0.9
        return -0.5 if spaced else -0.24
    if edge in {'[', '{'}:
        if len(before) == 2 and before[0] in {'"', "'"}:
            return -0.7  # A quoted bracket, rather than a quoted key.
        if edge == '[':
            value = (-5.1 if single else -4.8) if spaced else (
                -4.25 if single else -4.55)
            if ':' in before:
                return value - 0.9
            return value + (0.6 if ']' in before and quote in before else 0.0)
        value = (-4.5 if single else -4.15) if spaced else (
            -4.7 if single else -5.2)
        return value + (1.5 if quote in before or '}' in before else 0.0)
    if edge == '(':
        function = previous.strip().lstrip('._').lower()
        value = -2.4 if spaced else -1.8
        if function in MESSAGE_FUNCTIONS:
            value = -1.25
        elif function in LOOKUP_FUNCTIONS:
            value = -2.55
        return value - (1.7 if len(before) > 1 else 0.0)
    if edge == '=':
        return -2.8 if before.endswith('==') else (-1.65 if single else -1.03)
    if edge in {',', ':'}:
        if before == ',':
            return -1.35 if single else -0.5
        return -1.7
    if edge == '<':
        return -2.3
    if edge in set('+&@`#'):
