    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = token.strip()
    value = 0.0
    if (text.endswith(('"', "'")) and not token.endswith(('\n', '\r'))
            and not any(c.isalnum() for c in text)):
        value = quote_strength(text[:-1], text[-1], token.startswith(' '), previous)
    elif text in {'【', '《', '『'}:
        value = -0.47 if text == '【' else -0.22
    elif text in {'“', '‘', '«', '「', '(“'}:
        last = previous.rstrip()[-1:] or 'START'
        if '(' in text:
            value = -1.4
        elif last in set(',.:='):
            value = -0.4
        else:
            value = 0.25 if previous.strip().lower() in DETERMINERS else 0.05
    return (doc, token), float(value)

programs.luna:
"""Predict negative activations on quotation-mark tokens, especially after delimiters.

Most tokens are predicted as quiet; quoted text and string-literal punctuation
are approximated by a small set of familiar quote characters.
"""

READS = ()

STRUCTURE = '([{,=:;'


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lstrip()
    quote_at = next((i for i, char in enumerate(token)
                     if char in '"\'“‘«‹《〈【'), -1)
    if quote_at < 0:
        return None, 0.0

    before = token[:quote_at]
    if before and all(char in STRUCTURE for char in before):
        return None, -3.5
    if quote_at == 0:
        if token[0] in '“‘«‹《〈【':
            return None, -0.4
        if len(token) == 1 and token[0] == "'":
            return None, -0.45
        return None, -0.9
    return None, -0.7

programs.sol:
"""Approximate a negative response to attached Latin s endings.

For detached s/S, the preceding character's kind and case determine the
response. Longer preceding tokens strengthen it; vowels and sibilants
weaken lowercase s. The figure abbreviation figs/FIGS is especially strong.
Short multi-letter s-ending fragments get a weaker response. Other tokens
are approximated as inactive. Only the previous token is kept, resetting
at each document boundary. Coefficients are fitted training averages, not
claims that every English plural has the same activation.
"""
import string

READS = ()
VOWELS = frozenset('aeiou')
LATIN = frozenset(string.ascii_letters)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    carry = (doc, token)
    last = previous[-1:]
    value = 0.001
    if token in ('s', 'S'):
        if not previous:
            value = -0.14
        elif last.isdigit():
            value = -0.07
        elif last.isspace():
            value = 0.14 if token == 's' else 0.08
        elif last not in LATIN:
            value = 0.06 if token == 's' else 0.02
        elif token == 'S' and not last.isupper():
            value = -0.15
        elif previous.strip().lower() == 'fig':
            value = -1.32 if token == 's' else -2.06
        else:
            length = min(6, len(previous.strip()))
            if token == 's':
                value = -0.60 - 0.05 * length
                if last.lower() in VOWELS:
                    value += 0.19
                elif last.lower() in 'sxz':
                    value += 0.53
                elif last.lower() == 'y':
                    value += 0.21
                elif last.lower() in 'mnlr':
                    value += 0.075
            else:
                value = -0.58 - 0.085 * length
                if last.lower() in 'sxz':
                    value += 0.45
    elif (token.isascii() and token.isalpha() and
          token.endswith(('s', 'S')) and last in LATIN):
        stem = token[:-1].lower()
        if len(token) == 2 and stem not in VOWELS and stem != 's':
            value = -0.20
        elif len(token) <= 4 and stem[-1] not in VOWELS and stem[-1] != 's':
            value = -0.10
        elif token.isupper():
            value = -0.06
    return carry, value

programs.haiku:
"""Bare 's'/'S' suffix tokens split off a word, with case and punctuation contexts."""
READS = ()

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]
    if tok not in ("s", "S") or len(toks) < 2:
        return None, 0.0
    prev = toks[-2]
    if prev[-1:].isalpha():
        if tok == "S" and prev[-1:].islower():
            return None, -0.1
        return None, -0.8
    if prev[-1:].isdigit():
        return None, -0.1
    return None, 0.1
